// D27 × P3 的费用字段夹具：d19-resume 的判据一侧与 d27-p3-entry 的入口一侧共用（ADR-144）。只读
const LEDGER = (limit: string) => `{"schema":1,"currency":"USD","unit":"micro_usd","scope":"task","limit_micro_usd":${limit},"next_attempt_id":1,"entries":[]}`
const costText = (swap: { budget?: string; requests?: string; ledger?: string } = {}, done = '[]') =>
  `{"product":"d27-p3","market":"US","target_count":9999,${swap.budget ?? '"budget_usd":1'},`
  + `"tasks":[{"keyword":"local","dimension":"category","platform":"tiktok"}],"done":${done},"offsets":{"0":5},"pages":{"0":1},"answered":{"0":1},"found":{"0":3},`
  + `"created_at":"2026-01-01T00:00:00.000Z","updated_at":"2026-01-01T00:00:00.000Z",${swap.requests ?? '"requests":0'},${swap.ledger ?? `"cost_ledger":${LEDGER('1000000')}`}}`
// [名, 写重复的文本, 位置, 被丢掉的前几处原文]
const P3: [string, string, string, string[]][] = [
  ['budget_usd', costText({ budget: '"budget_usd":9.5e1,"budget_usd":1' }), 'budget_usd', ['9.5e1']],
  ['requests', costText({ requests: '"requests":7.5e1,"requests":0' }), 'requests', ['7.5e1']],
  ['cost_ledger', costText({ ledger: `"cost_ledger":${LEDGER('9.5e7')},"cost_ledger":${LEDGER('1000000')}` }), 'cost_ledger', ['{…}', '{…}']],
  ['cost_ledger-limit', costText({ ledger: `"cost_ledger":${LEDGER('9.5e7,"limit_micro_usd":1000000')}` }), 'cost_ledger["limit_micro_usd"]', ['9.5e7']],
]

await group('d19-resume', () => {
suite('D19', '续跑进度字段先验校验')
{
  const fromToken = (field: 'done' | 'pages', token: string): string[] => {
    const source = field === 'done'
      ? `{"done":[${token}],"pages":{"0":0}}`
      : `{"done":[0],"pages":{"0":${token}}}`
    const parsed = readCostDocument<{ done: unknown; pages: unknown }>(source)
    return resumeProgressProblems(parsed, 2, (holder, key) => sourceNumberToken(parsed, holder, key))
  }
  eq('恢复进度：原始 JSON 小数和指数只有精确等于整数时通过',
    ['1.0', '1e0', '1e+0', '1.00e0'].map(token =>
      [fromToken('done', token), fromToken('pages', token)]),
    [[[], []], [[], []], [[], []], [[], []]])
  eq('恢复进度：舍入为整数、下溢为零、精度越界和溢出都按原始数字拒绝',
    [fromToken('done', '0.99999999999999999'), fromToken('pages', '1e-325'),
      fromToken('pages', '9007199254740990.5'), fromToken('pages', '1e400')]
      .map(problems => problems.length > 0), [true, true, true, true])
  eq('恢复进度：无限大按原始指数报告，不把它写成 null',
    fromToken('pages', '1e400').some(problem => problem.includes('1e400') && !problem.includes('null')), true)

  const base = () => ({ done: [0, 2], offsets: { 0: 0, 2: 80 },
    answered: { 0: 0, 2: 3 }, found: { 0: null, 2: 40 }, pages: { 0: 0, 2: 12 } })
  const badDone: [string, unknown][] = [
    ['缺席', undefined], ['null', null], ['字符串', '0'], ['对象', { 0: 1 }],
    ['重复', [0, 0]], ['负数', [-1]], ['越界', [3]], ['小数', [0.5]],
    ['溢出', [Number.MAX_SAFE_INTEGER + 1]], ['字符串项', ['0']],
  ]
  const doneFailures = badDone.flatMap(([name, done]) => {
    const raw: Record<string, unknown> = { ...base(), done }
    if (name === '缺席') delete raw.done
    const got = resumeProgressProblems(raw, 3)
    return got.some(p => p.includes('done')) ? [] : [name]
  })
  eq('恢复进度：done 缺席、非数组、重复或非法任务索引逐类报错', doneFailures, [])
  criterion('D19.a')

  const tables = ['offsets', 'answered', 'found', 'pages'] as const
  const badTables: [string, unknown][] = [
    ['null', null], ['数组', [0]], ['字符串', '0'], ['数字', 0],
    ['负数', { 0: -1 }], ['小数', { 0: 0.5 }],
    ['溢出', { 0: Number.MAX_SAFE_INTEGER + 1 }], ['字符串值', { 0: '1' }],
    ['带前导零键', { '00': 1 }], ['负数键', { '-1': 1 }],
    ['越界键', { 3: 1 }], ['指数键', { '1e0': 1 }], ['非索引键', { abc: 1 }],
  ]
  eq('恢复进度：四张表均拒绝坏容器、坏索引与坏值，问题点名原字段',
    tables.flatMap(field => badTables.flatMap(([name, value]) =>
      resumeProgressProblems({ ...base(), [field]: value }, 3).some(p => p.includes(field))
        ? [] : [`${field}/${name}`])), [])
  eq('恢复进度：只有 found 允许 null，其他表的 null 仍被拒绝',
    tables.map(field => resumeProgressProblems({ ...base(), [field]: { 0: null } }, 3)
      .some(p => p.includes(field))), [true, true, false, true])
  criterion('D19.b')

  const bad = { done: [0, 0, 5], offsets: { '01': -3, 2: 0.2 },
    answered: { 9: -1 }, found: { 0: 'missing' }, pages: { 1: null } }
  const before = JSON.stringify(bad)
  const problems = resumeProgressProblems(bad, 3)
  eq('恢复进度：同一任务文件里的各表问题全部报告且不改原输入',
    [tables.every(field => problems.some(p => p.includes(field))),
      problems.some(p => p.includes('done')), JSON.stringify(bad) === before], [true, true, true])
  criterion('D19.c')

  const legacy = { done: [0], tasks: ['placeholder'] }
  eq('恢复进度：旧目录的四张整表可缺席；页数高于当前上限仍是有效历史',
    [resumeProgressProblems(legacy, 3), resumeProgressProblems(base(), 3)], [[], []])
  eq('恢复进度：两位任务索引与最大安全整数仍可作为历史进度读取',
    resumeProgressProblems({ done: [10], offsets: { 10: Number.MAX_SAFE_INTEGER },
      answered: { 10: Number.MAX_SAFE_INTEGER }, found: { 10: null }, pages: { 10: 12 } }, 11), [])
  eq('恢复进度：表之间不要求互相推算或补齐',
    resumeProgressProblems({ done: [1], offsets: { 0: 0 }, answered: { 2: 4 },
      found: { 1: null }, pages: { 2: 12 } }, 3), [])
  criterion('D19.d')

  // D19.k：进度键写了不止一次。JSON.parse 只留最后一处 —— "found":{"917":1e400,"917":4.00e1} 读进来是合法的 40，1e400 不见了。
  // 走 collect 与 render 的同一接法（readCostDocument 读入，按原文 token 与原文里的重复键判）。期望只来自判据原文与下面写进夹具的字面值：
  // 一千个任务，索引 917 与各处原文都是夹具里独有的写法，问题里找得到就不是碰巧。合法的那一份用不规范写法 8.0e1、0.3e1、4.00e1、1.20e1
  // （D19.b 允许，精确等于 80、3、40、12）；每个用例只在它前面多写几处，所以「只留最后一处」就是 LEGAL 本身 —— 它不报问题（阳性对照），拒绝只能是因为重复
  {
    const N = 1000
    const LEGAL = { done: '"done":[917]', offsets: '"offsets":{"917":8.0e1}', answered: '"answered":{"917":0.3e1}',
      found: '"found":{"917":4.00e1}', pages: '"pages":{"917":1.20e1}' }
    type Field = keyof typeof LEGAL
    const doc = (swap: Partial<Record<Field, string>> = {}, tail = '') =>
      `{${(Object.keys(LEGAL) as Field[]).map(field => swap[field] ?? LEGAL[field]).join(',')}${tail}}`
    const judged = (text: string): string[] | { threw: string } => {
      try {
        const parsed = readCostDocument<Record<string, unknown>>(text)
        return resumeProgressProblems(parsed, N, (holder, key) => sourceNumberToken(parsed, holder, key), sourceDuplicateKeys(parsed))
      } catch (error) { return { threw: error instanceof Error ? error.message : String(error) } }
    }
    // 一条问题里按先后找得到 ordered 的每一处（后一处从前一处的末尾往后找）
    const inOrder = (line: string, ordered: readonly string[]) => {
      let at = 0
      for (const token of ordered) { const i = line.indexOf(token, at); if (i < 0) return false; at = i + token.length }
      return true
    }
    // [名, 文本, 该点名的（头一个是字段）, 按文件先后的原文]：有问题、问题全在那个字段、有一条点齐名字并按先后列出原文。
    // 合格的交回 []，不合格的连同实际问题交回，红的时候看得到错值
    type DupCase = readonly [string, string, readonly string[], readonly string[]]
    const misses = (cases: readonly DupCase[], extra: (line: string) => boolean = () => true) =>
      cases.flatMap(([name, text, names, ordered]) => {
        const problems = judged(text)
        const hit = Array.isArray(problems) && problems.length > 0 && problems.every(p => p.includes(names[0]))
          && problems.some(p => names.every(n => p.includes(n)) && inOrder(p, ordered) && extra(p))
        return hit ? [] : [`${name}: ${JSON.stringify(problems)}`]
      })
    const ROOT: DupCase[] = [
      ['done', doc({ done: `"done":7.50e0,${LEGAL.done}` }), ['done'], ['7.50e0']],
      ['offsets', doc({ offsets: `"offsets":-2.5e1,${LEGAL.offsets}` }), ['offsets'], ['-2.5e1']],
      // 字符串照原文：盘上写的是转义的 u002d，解码后才是连字符，列得出 u002dfirst 才是原文
      ['answered', doc({ answered: `"answered":"zq\\u002dfirst",${LEGAL.answered}` }), ['answered'], ['u002dfirst']],
      ['found', doc({ found: `"found":{"618":7},${LEGAL.found}` }), ['found'], []],
      ['pages', doc({ pages: `"pages":[618,716],${LEGAL.pages}` }), ['pages'], []],
    ]
    const TABLE: DupCase[] = [
      ['offsets', doc({ offsets: '"offsets":{"917":1e400,"917":8.0e1}' }), ['offsets', '917'], ['1e400', '8.0e1']],
      ['answered', doc({ answered: '"answered":{"917":"zq\\u002dfirst","917":0.3e1}' }), ['answered', '917'], ['u002dfirst', '0.3e1']],
      // 两处都合法（525 与 40）：判的是重复本身，不是哪一处的值
      ['found', doc({ found: '"found":{"917":5.250e2,"917":4.00e1}' }), ['found', '917'], ['5.250e2', '4.00e1']],
      ['pages', doc({ pages: '"pages":{"917":9.75e0,"917":1.20e1}' }), ['pages', '917'], ['9.75e0', '1.20e1']],
    ]
    const ESCAPED: DupCase[] = [
      ['found', doc({ found: '"found":{"917":1e400,"91\\u0037":4.00e1}' }), ['found', '917'], ['1e400', '4.00e1']],
      ['pages', doc({ pages: '"pages":1e400,"p\\u0061ges":{"917":1.20e1}' }), ['pages'], ['1e400']],
    ]
    const THRICE: DupCase[] = [
      ['pages-table', doc({ pages: '"pages":{"917":5.250e2,"917":7.10e1,"917":1.20e1}' }), ['pages', '917'], ['5.250e2', '7.10e1', '1.20e1']],
      ['pages-root', doc({ pages: `"pages":1e400,"pages":"zz\\u002dmid",${LEGAL.pages}` }), ['pages'], ['1e400', 'u002dmid']],
    ]
    // 对象与数组只标出是哪一种：一样长的 [618,716] 与 {"618":7} 两份问题必须不同（标出了种类），且都不带 618（没有展开内容）
    const containers = [
      ['root', doc({ done: `"done":[618,716],${LEGAL.done}` }), doc({ done: `"done":{"618":7},${LEGAL.done}` }), ['done']],
      ['table', doc({ pages: '"pages":{"917":[618,716],"917":1.20e1}' }), doc({ pages: '"pages":{"917":{"618":7},"917":1.20e1}' }), ['pages', '917']],
    ] as const
    // 夹具有效：普通 JSON.parse 把每一份都读成与 LEGAL 一模一样的值 —— 前几处读入后不留痕迹，留下的最后一处合法
    eq('重复键夹具有效：普通 JSON.parse 把每一份写了重复键的进度都读成只留最后一处的合法那一份',
      [...ROOT, ...TABLE, ...ESCAPED, ...THRICE, ...containers.flatMap(([name, a, o]) => [[`${name}-array`, a], [`${name}-object`, o]])]
        .filter(([, text]) => !isDeepStrictEqual(JSON.parse(text), JSON.parse(doc()))).map(([name]) => name), [])
    eq('恢复进度：根上 done、offsets、answered、found、pages 任一键写了不止一次即不合规，即使最后一处合法；问题点名该字段，数字与字符串照原文列出',
      misses(ROOT), [])
    eq('恢复进度：offsets、answered、found、pages 表里同一个任务索引写了不止一次即不合规，最后一处合法、哪怕每一处都合法也一样；问题点名字段与键，按文件先后列出每一处原文',
      misses(TABLE), [])
    eq('恢复进度：按 JSON 解码后相同的键也算重复 —— 表里的 "917" 与 "91\\u0037"，根上的 pages 与 "p\\u0061ges"', misses(ESCAPED), [])
    // D19.k 说的是表里「同一个键」，不只是任务索引（main 审计 2026-10-12 第 3 条）：enrich 与 calibration version 不判进度的值，
    // 表里写了两次的 "zq" 只有这一条拦着。走它们的同一接法（只判重复，不判值）：表里多一个写了两次的 "zq"，前一处的
    // 5.250e2、7.10e1 这些读入后不留痕迹；只留最后一处的同一份不报问题（阳性对照），有问题只能是因为重复。
    // 原文里都不含 zq（answered 那一处是 yy-first），问题里找得到 zq 只能是在点名键
    const NON_INDEX: [Field, string, string, readonly string[]][] = [
      ['offsets', '"offsets":{"917":8.0e1,"zq":5.250e2,"zq":8.0e1}', '"offsets":{"917":8.0e1,"zq":8.0e1}', ['5.250e2', '8.0e1']],
      ['answered', '"answered":{"917":0.3e1,"zq":"yy\\u002dfirst","zq":0.3e1}', '"answered":{"917":0.3e1,"zq":0.3e1}', ['u002dfirst', '0.3e1']],
      ['found', '"found":{"917":4.00e1,"zq":7.10e1,"z\\u0071":4.00e1}', '"found":{"917":4.00e1,"zq":4.00e1}', ['7.10e1', '4.00e1']],
      ['pages', '"pages":{"917":1.20e1,"zq":9.75e0,"zq":1.20e1}', '"pages":{"917":1.20e1,"zq":1.20e1}', ['9.75e0', '1.20e1']],
    ]
    const dupOnly = (text: string): string[] | { threw: string } => {
      try { return duplicateProgressProblems(sourceDuplicateKeys(readCostDocument<Record<string, unknown>>(text))) }
      catch (error) { return { threw: error instanceof Error ? error.message : String(error) } }
    }
    eq('恢复进度：表里不是任务索引的键写了不止一次同样不合规 —— 只判重复的那一接法也点名字段与键，按文件先后列出每一处原文；只留最后一处的同一份不报',
      NON_INDEX.flatMap(([field, dup, last, ordered]) => {
        const [got, control] = [dupOnly(doc({ [field]: dup })), dupOnly(doc({ [field]: last }))]
        const fine = Array.isArray(got) && got.some(p => p.includes(field) && p.includes('zq') && inOrder(p, ordered))
          && isDeepStrictEqual(control, []) && isDeepStrictEqual(JSON.parse(doc({ [field]: dup })), JSON.parse(doc({ [field]: last })))
        return fine ? [] : [`${field}: 重复=${JSON.stringify(got)} 对照=${JSON.stringify(control)}`]
      }), [])
    // 字段、键 917、一千个任务与三处原文里都没有 3，问题里出现 3（或「三」）只能是在写出现次数
    eq('恢复进度：同一个键出现三次时写出出现次数，三处原文按文件先后全部列出（表里与根上各一份）',
      misses(THRICE, line => /[3三]/.test(line)), [])
    eq('恢复进度：重复键的某一处是对象或数组时，问题只标出它是对象还是数组，不展开其中内容',
      containers.flatMap(([name, asArray, asObject, names]) => {
        const [a, o] = [judged(asArray), judged(asObject)]
        const fine = [a, o].every(problems => Array.isArray(problems) && problems.some(p => names.every(n => p.includes(n)))
          && !problems.some(p => p.includes('618'))) && JSON.stringify(a) !== JSON.stringify(o)
        return fine ? [] : [`${name}: 数组=${JSON.stringify(a)} 对象=${JSON.stringify(o)}`]
      }), [])
    eq('恢复进度：重复键阳性对照 —— 只留最后一处的同一份进度合规，四张表各有同一个索引 917 也不算重复', judged(doc()), [])
    eq('恢复进度：重复键阳性对照 —— tasks 数组里几个任务对象各写一遍同名键不算重复',
      judged(doc({}, ',"tasks":[{"keyword":"a","dimension":"category","platform":"tiktok"},{"keyword":"b","dimension":"scene","platform":"tiktok"}]')), [])
    // 复核发现（ADR-140 第五节）：判据只管根上的五个进度键与四张表，别处的重复不由它判（D19.k 末句），也就不能让合规的进度被拒（D19.j）——
    // 根上别的键、根下别的对象、不在那两层的同名进度键（根下别的对象里、任务对象里）
    const OUTSIDE: [string, string][] = [
      ['根上别的键', doc({}, ',"budget_usd":1,"budget_usd":2')],
      ['根下别的对象', doc({}, ',"brand_calibration":{"a":1,"a":2}')],
      ['根下别的对象里同名的进度表', doc({}, ',"brand_calibration":{"found":{"917":1,"917":2}}')],
      ['任务对象里同名的进度键', doc({}, ',"tasks":[{"found":1,"found":2}]')],
    ]
    eq('恢复进度：根与四张表以外位置上的重复键不让进度不合规 —— 根上别的键、根下别的对象、更深处同名的进度键都不算',
      OUTSIDE.flatMap(([name, text]) => {
        const problems = judged(text)
        return Array.isArray(problems) && problems.length === 0 ? [] : [`${name}: ${JSON.stringify(problems)}`]
      }), [])
    // 复核发现（ADR-140 第五节）：读得进来的文件里有九百万字的字符串（这里是根上的 notes），判据不抛异常、不带堆栈；
    // 没有重复照样合规（D19.j），重复写在它后面照样点名 —— 扫描确实越过了它
    const LONG = `"notes":"${'x'.repeat(9_000_000)}",`
    const longFirst = (text: string) => `{${LONG}${text.slice(1)}`
    eq('恢复进度：读得进来的任务文件里有超长字符串时照常判 —— 没有重复就合规，写在它后面的重复照样点名并列出原文',
      [judged(longFirst(doc())), misses([['long', longFirst(doc({ found: '"found":{"917":1e400,"917":4.00e1}' })), ['found', '917'], ['1e400', '4.00e1']]])
        .map(miss => miss.slice(0, 300))], [[], []])
    // 字符串在重复的两处之间、里面有转义的引号（\"}）或以转义的反斜杠结尾（\\）：都在字符串里面，那张表没有到此为止，
    // 两处照样认得出、列得出。表里多出的键 "x" 另报「不是任务索引」，那一条也点名 found
    const between = (inside: string) => doc({ found: `"found":{"917":1e400,"x":"${inside}","917":4.00e1}` })
    const QUOTED: DupCase[] = [
      ['escaped-quote', between('\\"}'), ['found', '917'], ['1e400', '4.00e1']],
      ['trailing-backslash', between('a\\\\'), ['found', '917'], ['1e400', '4.00e1']],
    ]
    eq('恢复进度：字符串里转义的引号与以反斜杠结尾的字符串不打乱判据 —— 写在它们后面的重复照样点名并列出原文', misses(QUOTED), [])
    // 复核发现（ADR-140 第五节）：读入时的原文找不到（这里是读入后做的副本）就无从核对有没有重复，判为不合规，不当成没有重复。
    // 「done 为空、没有统计表」别的判据都没话说；同一份不做副本时合规是阳性对照
    const plain = readCostDocument<Record<string, unknown>>('{"done":[]}'), copied = structuredClone(plain)
    const withDuplicates = (raw: Record<string, unknown>) =>
      resumeProgressProblems(raw, N, (holder, key) => sourceNumberToken(raw, holder, key), sourceDuplicateKeys(raw))
    eq('恢复进度：找不到读入时原文的任务无从核对重复键，判为不合规而不是当成没有重复',
      [withDuplicates(plain), withDuplicates(copied).length > 0], [[], true])
    criterion('D19.k')
  }

  // D19.g、D19 × P1（ADR-138）：整份写回 task.json 后，读不出精确值的进度数字照原文留下，collect 仍按原文拒绝。
  // 期望只来自下面写进夹具的字面值；盘上原文由 diskTokens 取，不借被测函数。两个任务：done 的 0.99999999999999999 舍入后是合法的 1。
  const attempt = <T>(run: () => T): T | { threw: string } => {
    try { return run() } catch (error) { return { threw: error instanceof Error ? error.message : String(error) } }
  }
  const INEXACT = [['done', 0, '0.99999999999999999'], ['offsets', '1', '2.0000000000000001'],
    ['answered', '0', '9007199254740993'], ['found', '1', '1e400'], ['pages', '0', '1e-325']] as const
  const literals = INEXACT.map(([, , token]) => token), paths = INEXACT.map(([field, key]) => [field, key])
  const STAMP = '2026-01-01T00:00:00.000Z'
  // 五张表各一项；budget 子句可去掉，造一份没有 budget_usd 键的任务。
  const progressText = (entries: readonly (readonly [string, string | number, string])[], budget = '"budget_usd":0.005,') =>
    `{"product":"p","market":"US","target_count":1,"created_at":"${STAMP}","updated_at":"${STAMP}",`
    + '"tasks":[{"keyword":"a","dimension":"category","platform":"tiktok"},{"keyword":"b","dimension":"scene","platform":"instagram"}],'
    + entries.map(([field, key, token]) => field === 'done' ? `"done":[${token}]` : `"${field}":{"${key}":${token}}`).join(',')
    + `,${budget}"requests":2,"cost_ledger":${JSON.stringify(costFixture(5000, 1, 1).cost_ledger)}}`
  const inexactText = progressText(INEXACT)
  // collect 的接法（见上面 fromToken）：按原文取 token 判进度。
  const problemsOf = (text: string | { threw: string }) => typeof text !== 'string' ? text : attempt(() => {
    const parsed = readCostDocument<Record<string, unknown>>(text)
    return resumeProgressProblems(parsed, 2, (holder, key) => sourceNumberToken(parsed, holder, key))
  })
  const namedBy = (text: string | { threw: string }) => {
    const problems = problemsOf(text)
    return Array.isArray(problems) ? INEXACT.map(([field, , token]) => problems.some(p => p.includes(field) && p.includes(token))) : problems
  }
  // 只有一处坏进度的任务（其余四张表合法）：有问题、问题全在那一张表、点名原文。
  const lone = (field: string, token: string) => (text: string | { threw: string }) => {
    const problems = problemsOf(text)
    return Array.isArray(problems)
      ? [problems.length > 0, problems.every(p => p.includes(field)), problems.some(p => p.includes(token))] : problems
  }
  const NEGATIVE = [['done', 0, '0'], ['offsets', '0', '0'], ['answered', '0', '0'], ['found', '1', '-1e400'], ['pages', '0', '1']] as const
  const SUBNORMAL = [['done', 0, '0'], ['offsets', '1', '3e-324'], ['answered', '0', '0'], ['found', '0', '5'], ['pages', '0', '1']] as const
  const negativeText = progressText(NEGATIVE), subnormalText = progressText(SUBNORMAL), noBudgetText = progressText(INEXACT, '')
  const negativeNamed = lone('found', '-1e400'), subnormalNamed = lone('offsets', '3e-324')
  const tokensOf = (entries: readonly (readonly [string, string | number, string])[]) => entries.map(([, , token]) => token)
  const pathsOf = (entries: readonly (readonly [string, string | number, string])[]) => entries.map(([field, key]) => [field, key])
  const onDisk = (text: string | { threw: string }, at: readonly (readonly (string | number)[])[] = paths) =>
    typeof text === 'string' ? diskTokens(text, at) : text
  eq('整份写回夹具有效：普通 JSON 往返会把五张进度表里读不出精确值的数字各改成另一个值',
    diskTokens(JSON.stringify(JSON.parse(inexactText)), paths), ['1', '2', '9007199254740992', 'null', '0'])
  eq('整份写回夹具有效：写回前 collect 按原文判定，五张进度表各被拒绝并点名原文', namedBy(inexactText), INEXACT.map(() => true))
  const root = mkdtempSync(join(tmpdir(), 'kol-d19g-'))
  try {
    const seeded = (name: string, text = inexactText) => { const dir = join(root, name); mkdirSync(dir); writeFileSync(join(dir, 'task.json'), text); return dir }
    const readBack = (dir: string, write: (dir: string) => void) => attempt(() => { write(dir); return rf(join(dir, 'task.json'), 'utf8') })
    const saved = readBack(seeded('save-task'), dir => saveTask(dir, loadTask(dir)))
    const checkpointed = readBack(seeded('cost-checkpoint'), dir => {
      new Budget(loadTask(dir), () => {}, snapshot => saveCostCheckpoint(dir, snapshot)).reserve(TEST_IG)
    })
    const edited = readBack(seeded('edited'), dir => {
      const state = loadTask(dir)
      state.offsets![1] = 7; state.found![1] = 3
      saveTask(dir, state)
    })
    eq('整份写回夹具有效：saveTask 与费用检查点确实写回了 task.json（updated_at 已刷新）',
      [saved, checkpointed].map(text => typeof text === 'string' ? JSON.parse(text).updated_at !== STAMP : text), [true, true])
    eq('saveTask 整份写回后，五张进度表里每个数字的原文与写回前盘上的原文相同', onDisk(saved), literals)
    eq('费用检查点写回后，五张进度表里每个数字的原文与写回前盘上的原文相同', onDisk(checkpointed), literals)
    eq('整份写回后 collect 按原文判定仍拒绝五张表并点名各自原文，溢出的 found 不被读成 null',
      [namedBy(saved), namedBy(checkpointed)], [INEXACT.map(() => true), INEXACT.map(() => true)])
    eq('整份写回时程序改过的进度照新值写：offsets 与 found 改成 7 与 3 后盘上就是 7 与 3',
      onDisk(edited, [['offsets', '1'], ['found', '1']]), ['7', '3'])
    eq('整份写回时同一份里没改过的 pages 仍是写回前盘上的原文', onDisk(edited, [['pages', '0']]), ['1e-325'])

    // enrich 改额：在读入的同一份对象上经 Budget 改额，再预留一次（触发费用检查点），然后整份 saveTask；根预算确实变了，进度原文照旧。
    let checkpoints = 0
    const changed = readBack(seeded('budget-change'), dir => {
      const state = loadTask(dir)
      const budget = new Budget(state, () => {}, snapshot => { saveCostCheckpoint(dir, snapshot); checkpoints++ })
      budget.setLimit(10000); budget.reserve(TEST_IG)
      saveTask(dir, state)
    })
    eq('改额整份写回夹具有效：费用检查点确实写过，盘上根预算确实从 0.005 改成 0.01，updated_at 已刷新',
      typeof changed === 'string' ? [checkpoints > 0, JSON.parse(changed).budget_usd, JSON.parse(changed).updated_at !== STAMP] : changed, [true, 0.01, true])
    eq('经 Budget 改额（带费用检查点）后在同一份对象上 saveTask 整份写回，五张进度表里每个数字的原文与写回前盘上的原文相同', onDisk(changed), literals)
    eq('改额后整份写回的任务，collect 按原文判定仍拒绝五张表并点名各自原文', namedBy(changed), INEXACT.map(() => true))

    // render（persistListAndStatus）与 saveTask 写回一份没有 budget_usd 键的任务。
    eq('无根预算写回夹具有效：任务里没有 budget_usd 键，写回前 collect 按原文拒绝五张表并点名原文',
      [Object.hasOwn(JSON.parse(noBudgetText), 'budget_usd'), namedBy(noBudgetText)], [false, INEXACT.map(() => true)])
    const noBudget = [readBack(seeded('no-budget-render', noBudgetText), dir => persistListAndStatus(dir, loadTask(dir), [], 'unknown')),
      readBack(seeded('no-budget-save', noBudgetText), dir => saveTask(dir, loadTask(dir)))]
    eq('无根预算写回夹具有效：persistListAndStatus 与 saveTask 确实写回了 task.json（updated_at 已刷新）',
      noBudget.map(text => typeof text === 'string' ? JSON.parse(text).updated_at !== STAMP : text), [true, true])
    eq('没有 budget_usd 键的任务经 persistListAndStatus 与 saveTask 整份写回后，五张进度表里每个数字的原文不变',
      noBudget.map(text => onDisk(text)), [literals, literals])
    eq('没有 budget_usd 键的任务整份写回后 collect 按原文判定仍拒绝五张表，溢出的 found 仍点名 1e400',
      noBudget.map(namedBy), [INEXACT.map(() => true), INEXACT.map(() => true)])

    // 负溢出与部分下溢：各一份只有那一处坏、其余四张表合法的任务，经 saveTask 与费用检查点各写回一次。
    eq('整份写回夹具有效：普通 JSON 往返会把负溢出的 found 改成 null、把部分下溢的 offsets 改成另一个次正规数 5e-324',
      [diskTokens(JSON.stringify(JSON.parse(negativeText)), [['found', '1']]), diskTokens(JSON.stringify(JSON.parse(subnormalText)), [['offsets', '1']])],
      [['null'], ['5e-324']])
    eq('整份写回夹具有效：写回前 collect 按原文判定，两份只坏一处的任务各只拒绝那一张表并点名原文 -1e400 与 3e-324',
      [negativeNamed(negativeText), subnormalNamed(subnormalText)], [[true, true, true], [true, true, true]])
    const writers = [(dir: string) => saveTask(dir, loadTask(dir)),
      (dir: string) => { new Budget(loadTask(dir), () => {}, snapshot => saveCostCheckpoint(dir, snapshot)).reserve(TEST_IG) }]
    const negative = writers.map((write, i) => readBack(seeded(`negative-${i}`, negativeText), write))
    const subnormal = writers.map((write, i) => readBack(seeded(`subnormal-${i}`, subnormalText), write))
    eq('整份写回夹具有效：负溢出与部分下溢两份任务经 saveTask 与费用检查点确实写回（updated_at 已刷新）',
      [...negative, ...subnormal].map(text => typeof text === 'string' ? JSON.parse(text).updated_at !== STAMP : text), [true, true, true, true])
    eq('saveTask 与费用检查点整份写回后，负溢出的 found 盘上原文仍是 -1e400，不写成 null，其余进度原文不变',
      negative.map(text => onDisk(text, pathsOf(NEGATIVE))), [tokensOf(NEGATIVE), tokensOf(NEGATIVE)])
    eq('负溢出的 found 整份写回后 collect 按原文判定仍只拒绝 found 并点名 -1e400',
      negative.map(negativeNamed), [[true, true, true], [true, true, true]])
    eq('saveTask 与费用检查点整份写回后，部分下溢的 offsets 盘上原文仍是 3e-324，不舍入成 5e-324，其余进度原文不变',
      subnormal.map(text => onDisk(text, pathsOf(SUBNORMAL))), [tokensOf(SUBNORMAL), tokensOf(SUBNORMAL)])
    eq('部分下溢的 offsets 整份写回后 collect 按原文判定仍只拒绝 offsets 并点名 3e-324',
      subnormal.map(subnormalNamed), [[true, true, true], [true, true, true]])

    // 值不变、只是写法不规范：五张表全合法，done 写 1e+0、offsets 写 2e0、answered 写 -0、found 写 1E0、pages 写 1.0
    // （D19.a、D19.b 允许：精确等于非负安全整数，-0 精确等于 0），经 saveTask 与费用检查点各写回一次。
    const VERBOSE = [['done', 0, '1e+0'], ['offsets', '0', '2e0'], ['answered', '0', '-0'], ['found', '0', '1E0'], ['pages', '0', '1.0']] as const
    const verboseText = progressText(VERBOSE), verbose = writers.map((write, i) => readBack(seeded(`verbose-${i}`, verboseText), write))
    eq('整份写回夹具有效：写成 1e+0、2e0、-0、1E0 与 1.0 的整数进度合法，collect 不拒绝；普通 JSON 往返会把它们改写成 1、2、0、1 与 1',
      [problemsOf(verboseText), diskTokens(JSON.stringify(JSON.parse(verboseText)), pathsOf(VERBOSE))], [[], ['1', '2', '0', '1', '1']])
    eq('整份写回夹具有效：写法不规范的合法进度经 saveTask 与费用检查点确实写回（updated_at 已刷新）',
      verbose.map(text => typeof text === 'string' ? JSON.parse(text).updated_at !== STAMP : text), [true, true])
    eq('saveTask 与费用检查点整份写回后，合法进度里写成 1e+0、2e0、-0、1E0 与 1.0 的整数盘上原文逐字不变，不改换写法',
      verbose.map(text => onDisk(text, pathsOf(VERBOSE))), [tokensOf(VERBOSE), tokensOf(VERBOSE)])

    // 未完成的任务、进度手写为 0 与 0.0（D19.b 允许，D19.d 不要求互相推算）：按 collect 的顺序推进，经费用检查点再 saveTask 整份写回。
    const ZERO = [['done', 0, ''], ['offsets', '0', '0'], ['answered', '0', '0'], ['found', '0', '0.0'], ['pages', '0', '0']] as const
    const zeroText = progressText(ZERO), advanced = readBack(seeded('zero-advanced', zeroText), dir => {
      const state = loadTask(dir)
      state.offsets![0] = 9; state.answered![0] = 3; state.found![0] = 5; state.pages![0] = 2
      new Budget(state, () => {}, snapshot => saveCostCheckpoint(dir, snapshot)).reserve(TEST_IG)
      saveTask(dir, state)
    })
    eq('整份写回夹具有效：done 为空、进度手写为 0 与 0.0 的未完成任务合法，collect 不拒绝；推进后确实写回（updated_at 已刷新）',
      [problemsOf(zeroText), typeof advanced === 'string' ? JSON.parse(advanced).updated_at !== STAMP : advanced], [[], true])
    eq('整份写回时原值为 0 的进度被改过后照新值写，不写回旧的 0', onDisk(advanced, pathsOf(ZERO).slice(1)), ['9', '3', '5', '2'])
  } finally { rmSync(root, { recursive: true, force: true }) }
  criterion('D19.g')
  tension('D19', 'P1')
}

suite('D27', 'task.json 任一层写重复的键：按读入时的原文认出，每一处按先后列出')
{
  // D27.a（ADR-142）。期望只来自 D27.a 原文、KeyDuplicate 类型与 duplicateKeyProblems 签名处的约定，以及下面写进夹具的字面值；
  // 没有读 sourceDuplicates、duplicateKeyProblems、sourceDuplicateKeys 的函数体。读法与 collect、render 读 task.json 相同：
  // readCostDocument 读入，sourceDuplicates 从读入时的原文里找写重复的键，duplicateKeyProblems 写成问题。
  // 每个用例只有一处写重复，前几处的原文是夹具里独有的写法（zq-old、7.5e1、zz-mid 这些），问题里找得到就不是碰巧；
  // 最后一处一律是基准那一份的值，所以普通 JSON.parse 读出来与基准一模一样（第一条断言），前几处只在原文里找得到
  type Scan = { dups: readonly KeyDuplicate[] | null; all: string[]; outside: string[] }
  const scan = (text: string): Scan | { threw: string } => {
    try {
      const parsed = readCostDocument<Record<string, unknown>>(text)
      const dups = sourceDuplicates(parsed)
      return { dups, all: duplicateKeyProblems(dups), outside: duplicateKeyProblems(dups, true) }
    } catch (error) { return { threw: error instanceof Error ? error.message : String(error) } }
  }
  // 位置的独立 oracle（D27.a 原文）：根上的键名，往下对象里的键接 ["键"]、数组里的元素接 [下标]
  const position = (path: readonly (string | number)[]) =>
    path.map((step, i) => i === 0 ? String(step) : typeof step === 'number' ? `[${step}]` : `[${JSON.stringify(step)}]`).join('')
  // 字符串照原文：盘上写的是 - 这种转义，列出来的也得是转义，解码后的连字符不算原文。
  // 列的时候连不连两端的引号判据没说，比较前去掉两端引号；数字、{…}、[…] 原样比
  const bare = (value: string) => /^".*"$/s.test(value) ? value.slice(1, -1) : value
  const inOrder = (line: string, ordered: readonly string[]) => {
    let at = 0
    for (const token of ordered) { const i = line.indexOf(token, at); if (i < 0) return false; at = i + token.length }
    return true
  }
  const BASE = {
    tasks: '"tasks":[{"keyword":"lamp","dimension":"category","platform":"tiktok"}]',
    done: '"done":[0]', offsets: '"offsets":{"0":5}', answered: '"answered":{"0":1}', found: '"found":{"0":3}', pages: '"pages":{"0":1}',
    budget: '"budget_usd":1', requests: '"requests":0',
    ledger: '"cost_ledger":{"schema":1,"limit_micro_usd":1000000,"entries":[{"endpoint":"a","unit_micro_usd":1000}]}',
    brand: '"brand_calibration":{"version":"v","natural_scenarios":["x"]}',
    matrix: '"matrix":[[0,{"k":1}]]', extra: '"extra":{"a":1}',
  }
  type Part = keyof typeof BASE
  const doc = (swap: Partial<Record<Part, string>> = {}) => `{${(Object.keys(BASE) as Part[]).map(part => swap[part] ?? BASE[part]).join(',')}}`
  // [名, 写了重复键的文本, 只留最后一处的文本, 写重复的位置, 按文件先后的每一处原文（去掉两端引号）, 是不是 D19.k 那几处]
  type DupCase = readonly [string, string, string, readonly (string | number)[], readonly string[], boolean]
  const one = (name: string, swap: Partial<Record<Part, string>>, path: readonly (string | number)[], values: readonly string[],
    d19k = false, last: Partial<Record<Part, string>> = {}): DupCase => [name, doc(swap), doc(last), path, values, d19k]
  const OUTSIDE: DupCase[] = [
    one('tasks-root', { tasks: `"tasks":"zq-first-list",${BASE.tasks}` }, ['tasks'], ['zq-first-list', '[…]']),
    one('task-keyword', { tasks: '"tasks":[{"keyword":"zq\\u002dold","dimension":"category","keyword":"lamp","platform":"tiktok"}]' },
      ['tasks', 0, 'keyword'], ['zq\\u002dold', 'lamp']),
    one('budget-root', { budget: '"budget_usd":9.5e1,"budget_usd":1' }, ['budget_usd'], ['9.5e1', '1']),
    one('requests-thrice', { requests: '"requests":7.5e1,"requests":"zz-mid","requests":0' }, ['requests'], ['7.5e1', 'zz-mid', '0']),
    one('ledger-entry', { ledger: '"cost_ledger":{"schema":1,"limit_micro_usd":1000000,"entries":[{"endpoint":"a","unit_micro_usd":6.5e2,"unit_micro_usd":1000}]}' },
      ['cost_ledger', 'entries', 0, 'unit_micro_usd'], ['6.5e2', '1000']),
    // 对象与数组只标出是哪一种，不展开：里面的 9.75e2 与 8.25e2 不该出现在问题里
    one('nested-arrays', { matrix: '"matrix":[[0,{"k":{"x":9.75e2},"k":[8.25e2],"k":1}]]' }, ['matrix', 0, 1, 'k'], ['{…}', '[…]', '1']),
    one('brand-inner', { brand: '"brand_calibration":{"version":"v","natural_scenarios":"zq-first-scene","natural_scenarios":["x"]}' },
      ['brand_calibration', 'natural_scenarios'], ['zq-first-scene', '[…]']),
    // D27.a 原文里的例子："a" 与 "a" 解码后同名；键名里的转义同样（keyword 与 keyword）
    one('escaped-a', { extra: '"extra":{"a":5.5e0,"\\u0061":1}' }, ['extra', 'a'], ['5.5e0', '1']),
    one('escaped-keyword', { tasks: '"tasks":[{"keyword":"zq-escaped","dimension":"category","k\\u0065yword":"lamp","platform":"tiktok"}]' },
      ['tasks', 0, 'keyword'], ['zq-escaped', 'lamp']),
    // 挨着 D19.k 的边界，都不是 D19.k 那几处：done 不是那四张表之一；表里更深一层；别的对象里叫 found 的表；任务对象里叫 found 的键
    one('done-object', { done: '"done":{"0":7.5e0,"0":0}' }, ['done', '0'], ['7.5e0', '0'], false, { done: '"done":{"0":0}' }),
    one('found-deep', { found: '"found":{"0":{"zq":7.25e0,"zq":3}}' }, ['found', '0', 'zq'], ['7.25e0', '3'], false, { found: '"found":{"0":{"zq":3}}' }),
    one('pages-array-deep', { pages: '"pages":{"0":[{"zq":8.5e0,"zq":1}]}' }, ['pages', '0', 0, 'zq'], ['8.5e0', '1'], false, { pages: '"pages":{"0":[{"zq":1}]}' }),
    one('brand-found-table', { brand: '"brand_calibration":{"version":"v","natural_scenarios":["x"],"found":{"0":9.5e0,"0":1}}' },
      ['brand_calibration', 'found', '0'], ['9.5e0', '1'], false, { brand: '"brand_calibration":{"version":"v","natural_scenarios":["x"],"found":{"0":1}}' }),
    one('task-found', { tasks: '"tasks":[{"keyword":"lamp","dimension":"category","platform":"tiktok","found":4.75e0,"found":1}]' },
      ['tasks', 0, 'found'], ['4.75e0', '1'], false, { tasks: '"tasks":[{"keyword":"lamp","dimension":"category","platform":"tiktok","found":1}]' }),
  ]
  // D19.k 那几处：根上五个进度键、四张表里直接写重复的任务索引（表里那一处的键用转义写一次）
  const PROGRESS: DupCase[] = [
    one('done-root', { done: '"done":7.5e0,"done":[0]' }, ['done'], ['7.5e0', '[…]'], true),
    one('offsets-root', { offsets: '"offsets":6.5e0,"offsets":{"0":5}' }, ['offsets'], ['6.5e0', '{…}'], true),
    one('answered-root', { answered: '"answered":"zq-first-answered","answered":{"0":1}' }, ['answered'], ['zq-first-answered', '{…}'], true),
    one('found-root', { found: '"found":[1e400],"found":{"0":3}' }, ['found'], ['[…]', '{…}'], true),
    one('pages-root', { pages: '"pages":1e400,"pages":{"0":1}' }, ['pages'], ['1e400', '{…}'], true),
    one('offsets-key', { offsets: '"offsets":{"0":1e400,"0":5}' }, ['offsets', '0'], ['1e400', '5'], true),
    one('answered-key', { answered: '"answered":{"0":2.5e0,"0":1}' }, ['answered', '0'], ['2.5e0', '1'], true),
    one('found-key', { found: '"found":{"0":9.25e2,"\\u0030":3}' }, ['found', '0'], ['9.25e2', '3'], true),
    one('pages-key', { pages: '"pages":{"0":4.5e0,"0":1}' }, ['pages', '0'], ['4.5e0', '1'], true),
  ]
  // 缩进写出的任务文件（saveTask 写回的就是带空白的）：原文不带两边的空白
  const pretty = JSON.stringify(JSON.parse(doc()), null, 2)
  const PRETTY: DupCase = ['pretty', pretty.replace('"budget_usd": 1', '"budget_usd": 9.5e1,\n  "budget_usd": 1'), pretty, ['budget_usd'], ['9.5e1', '1'], false]
  const CASES = [...OUTSIDE, ...PROGRESS, PRETTY]
  eq('任一层写重复的键夹具有效：普通 JSON.parse 把每一份都读成只留最后一处的那一份，前几处读入后不留痕迹',
    CASES.filter(([, text, last]) => text === last || !isDeepStrictEqual(JSON.parse(text), JSON.parse(last))).map(([name]) => name), [])
  // 结构：每份恰好一处写重复，位置是对象里的键名与数组里的下标（类型上分得开），每一处原文按先后
  const structured = (cases: readonly DupCase[]) => cases.flatMap(([name, text, , path, values]) => {
    const got = scan(text)
    const fine = 'dups' in got && got.dups !== null && got.dups.length === 1
      && isDeepStrictEqual([...got.dups[0].path], [...path]) && isDeepStrictEqual(got.dups[0].values.map(bare), [...values])
    return fine ? [] : [`${name}: ${JSON.stringify('dups' in got ? got.dups : got)}`]
  })
  eq('任一层写重复的键：根上、对象里、数组元素里任一层同一对象写了不止一次的键都认得出，即使最后一处合法；位置逐层是键名与下标，每一处原文按文件先后',
    structured([...OUTSIDE, ...PROGRESS]), [])
  eq('任一层写重复的键：按 JSON 解码后相同的键也算重复 —— "a" 与 "\\u0061"、keyword 与 k\\u0065yword、表里的 "0" 与 "\\u0030"',
    structured(CASES.filter(([name]) => ['escaped-a', 'escaped-keyword', 'found-key'].includes(name))), [])
  eq('任一层写重复的键：缩进写出的任务文件里每一处原文不带两边的空白', structured([PRETTY]), [])
  // 问题：每一处写重复的键恰好一条，写出位置（独立 oracle 拼出的那一串）与按先后的每一处原文
  const written = (cases: readonly DupCase[], extra: (line: string) => boolean = () => true) => cases.flatMap(([name, text, , path, values]) => {
    const got = scan(text)
    const fine = 'all' in got && got.all.length === 1 && got.all[0].includes(position(path)) && inOrder(got.all[0], values) && extra(got.all[0])
    return fine ? [] : [`${name}: ${JSON.stringify('all' in got ? got.all : got)}`]
  })
  eq('任一层写重复的键：每一处写重复的键一条问题，写出位置（根上的键名往下接 ["键"] 与 [下标]）并按文件先后列出每一处原文',
    written(CASES), [])
  eq('任一层写重复的键：问题写出出现次数 —— 写了两次的写出 2，写了三次的写出 3',
    [...written(CASES.filter(([name]) => name === 'budget-root'), line => /[2两二]/.test(line)),
      ...written(CASES.filter(([name]) => name === 'requests-thrice'), line => /[3三]/.test(line))], [])
  eq('任一层写重复的键：某一处是对象或数组时问题只标出是对象还是数组，不展开其中内容',
    CASES.filter(([name]) => name === 'nested-arrays').flatMap(([name, text]) => {
      const got = scan(text)
      return 'all' in got && got.all.length === 1 && !/9\.75e2|8\.25e2|"x"/.test(got.all[0]) ? [] : [`${name}: ${JSON.stringify(got)}`]
    }), [])
  // 位置要读得出（复核发现 4，写在接上实现之后）：根上的键为空、或含字母、数字与 _ . - 以外的字符时也写成 ["键"]，
  // 键名里的引号、反斜杠与控制字符按 JSON 转义 —— 空的位置读不出，控制字符原样进终端，根上的 x["y"] 会与 x 里的 y 混同
  const ODD: [string, string, boolean][] = [['root-empty', '', false], ['root-control', 'a\u001b[31m', false], ['root-brackets', 'x["y"]', false],
    ['inner-quote', 'a"b', true], ['inner-backslash', 'a\\b', true]]
  eq('任一层写重复的键：位置读得出 —— 根上的键为空或含字母、数字与 _ . - 以外的字符时也写成 ["键"]，键名里的引号、反斜杠与控制字符按 JSON 转义，不把控制字符原样写出',
    ODD.flatMap(([name, key, inner]) => {
      const k = JSON.stringify(key), at = inner ? `x[${k}]` : `[${k}]`
      const got = scan(inner ? `{"x":{${k}:7.5e0,${k}:1}}` : `{${k}:7.5e0,${k}:1,"x":{"y":1}}`)
      return 'all' in got && got.all.length === 1 && got.all[0].startsWith(at) && !/[\u0000-\u001f]/.test(got.all[0]) ? [] : [`${name}: ${JSON.stringify(got)}`]
    }), [])
  // 反方向（main 审计 2026-10-12 第 4 条）：根上只含字母、数字与 _ . - 的键照原样写，不加 ["…"]。上面「写出位置」那条用 includes 比，
  // ["budget_usd"] 也包含 budget_usd，加了括号照样绿；这里问题从独立 oracle 拼出的位置开头（与上一条同一种比法），根上的键不带括号
  eq('任一层写重复的键：根上只含字母、数字与 _ . - 的键照原样写出位置，不写成 ["键"] —— 问题以 budget_usd、tasks[0]["keyword"] 这样的位置开头',
    CASES.flatMap(([name, text, , path]) => {
      const got = scan(text)
      return 'all' in got && got.all.length === 1 && got.all[0].startsWith(position(path)) ? [] : [`${name}: ${JSON.stringify('all' in got ? got.all : got)}`]
    }), [])
  // outsideProgress：只跳过 D19.k 那几处（那几处由 duplicateProgressProblems 报），挨着边界的其余位置一处不少
  eq('任一层写重复的键：只报 D19.k 以外那几处时跳过根上五个进度键与四张表里的键，别处的照报 —— 包括 done 里的键、表里更深一层、别的对象里叫 found 的表与任务对象里叫 found 的键',
    CASES.flatMap(([name, text, , , , d19k]) => {
      const got = scan(text)
      const fine = 'all' in got && got.all.length === 1 && (d19k ? got.outside.length === 0 : isDeepStrictEqual(got.outside, got.all))
      return fine ? [] : [`${name}: ${JSON.stringify('outside' in got ? got.outside : got)}`]
    }), [])
  // 不多拒：不同对象里的同名键（两个任务各有 keyword、四张表各有 "0"、费用账两项各有同名键、对象里套着同名的对象）、
  // 数组里相同的元素、字符串里长得像重复键的文字、解码后不同名的键（"a" 与 "aa"、键名里转义的引号）都不算
  const CLEAN = '{"tasks":[{"keyword":"lamp","dimension":"category","platform":"tiktok"},{"keyword":"lamp","dimension":"category","platform":"tiktok"}],'
    + '"done":[0,0,1],"offsets":{"0":5,"1":5},"answered":{"0":5,"1":5},"found":{"0":5,"1":5},"pages":{"0":5,"1":5},'
    + '"cost_ledger":{"entries":[{"endpoint":"a","unit_micro_usd":1000},{"endpoint":"a","unit_micro_usd":1000}]},'
    + '"nest":{"k":{"k":{"k":1}},"j":{"k":1}},"list":[{"a":1},{"a":1},[1,1],[1,1],"x","x",null,null],'
    + '"brand_calibration":{"found":{"0":1},"tasks":[{"keyword":"x"}]},"notes":"\\"a\\":1,\\"a\\":2,{\\"b\\":1,\\"b\\":2}",'
    + '"esc":{"a":1,"\\u0062":2,"a\\u0061":3,"q\\"x":4,"q":5}}'
  const clean = scan(CLEAN)
  eq('任一层写重复的键不多拒：不同对象里的同名键、数组里相同的元素、字符串里像重复键的文字与解码后不同名的键都不算重复',
    'dups' in clean ? [clean.dups, clean.all, clean.outside] : clean, [[], [], []])
  // D27.e 判据那一半在这里认领（复核发现 1）：入口那一半由自检认领，但任何一种多拒的扫描都会让自检里带费用账条目的阳性对照
  // 一并失败、带上夹具记号，自检那边的负片按规矩记不上功；判据这一层没有夹具记号，负片记在这里
  criterion('D27.e')
  // 读得进来的深层嵌套与超长字符串（D19.k 那条复核发现的同类）：不抛异常，写在里面或后面的重复照样认出
  const DEPTH = 2400
  const deepText = doc({ matrix: `"matrix":${'['.repeat(DEPTH)}{"a":5.5e0,"a":1}${']'.repeat(DEPTH)}` })
  const longText = `{"notes":"${'x'.repeat(9_000_000)}",${doc({ budget: '"budget_usd":9.5e1,"budget_usd":1' }).slice(1)}`
  const deep = scan(deepText), long = scan(longText)
  eq('任一层写重复的键：读得进来的深层嵌套与超长字符串照常判，不抛异常，写在里面或后面的重复照样认出并列出原文',
    [JSON.parse(deepText) !== undefined && JSON.parse(longText) !== undefined,
      'dups' in deep && deep.dups?.length === 1 && isDeepStrictEqual([...deep.dups[0].path], ['matrix', ...Array(DEPTH).fill(0), 'a'])
        && deep.all.length === 1 && inOrder(deep.all[0], ['5.5e0', '1']) ? true : JSON.stringify(deep).slice(0, 300),
      'dups' in long && long.dups?.length === 1 && long.all.length === 1 && long.all[0].includes('budget_usd') && inOrder(long.all[0], ['9.5e1', '1'])
        ? true : JSON.stringify(long).slice(0, 300)], [true, true, true])
  // 找不到读入时的原文（读入后的副本、普通 JSON.parse 读出的对象）就无从核对：交回 null，写成问题，不当成没有重复（两种模式都是）。
  // 同一份不做副本时没有重复、没有问题是阳性对照
  const plainDoc = readCostDocument<Record<string, unknown>>(doc())
  const unknowns = [structuredClone(plainDoc), JSON.parse(doc())].map(root => sourceDuplicates(root))
  eq('任一层写重复的键：找不到读入时原文的任务无从核对，判为有问题而不是当成没有重复',
    [sourceDuplicates(plainDoc), duplicateKeyProblems(sourceDuplicates(plainDoc)), unknowns,
      duplicateKeyProblems(null).length > 0, duplicateKeyProblems(null, true).length > 0], [[], [], [null, null], true, true])
  criterion('D27.a')

  // D19.k 的判据范围不因 D27 变宽：同一份文件里既有 D19.k 那几处又有更深的重复时，sourceDuplicateKeys 与 D19.k 的问题只有那几处；
  // 更深一层的 zq-old、6.5e0、4.5e0、3.5e0 一处都不出现（它们归 D27，由 duplicateKeyProblems 报）
  const MIXED = '{"tasks":[{"keyword":"zq-old","keyword":"lamp","dimension":"category","platform":"tiktok"}],"done":[0],'
    + '"pages":7.5e1,"pages":{"0":1},"found":{"0":9.5e1,"0":3,"1":{"zq":6.5e0,"zq":8}},"answered":{"0":[{"zq":4.5e0,"zq":2}]},'
    + '"cost_ledger":{"entries":[{"http_200_count":3.5e0,"http_200_count":1}]}}'
  let mixedRead: Record<string, unknown> | undefined, mixedThrew = ''
  try { mixedRead = readCostDocument<Record<string, unknown>>(MIXED) } catch (error) { mixedThrew = error instanceof Error ? error.message : String(error) }
  const keys = mixedRead === undefined ? undefined : sourceDuplicateKeys(mixedRead)
  const progressHalf = keys === undefined || keys === null ? `threw=${mixedThrew} keys=${keys}` : {
    shape: keys.map(({ parent, key, values }) => ({ parent: parent ?? null, key, values: [...values] }))
      .sort((a, b) => `${a.parent}/${a.key}`.localeCompare(`${b.parent}/${b.key}`)),
    problems: [duplicateProgressProblems(keys).length, duplicateProgressProblems(keys).some(p => /zq-old|6\.5e0|4\.5e0|3\.5e0/.test(p))] }
  eq('D19.k 的判据范围不变：同一份里又有更深的重复时，进度键那一半只认根上的 pages 与 found 表里的 "0" 两处，不报更深的那几处',
    progressHalf, { shape: [{ parent: 'found', key: '0', values: ['9.5e1', '3'] }, { parent: null, key: 'pages', values: ['7.5e1', '{…}'] }],
      problems: [2, false] })
  const deeper = mixedRead === undefined ? `threw=${mixedThrew}` : duplicateKeyProblems(sourceDuplicates(mixedRead), true)
  eq('任一层写重复的键：同一份里又有进度键的重复时，只报 D19.k 以外那几处的判据把更深的四处各报一次，不报进度键那两处',
    Array.isArray(deeper) ? [deeper.length, ['zq-old', '6.5e0', '4.5e0', '3.5e0'].map(token => deeper.filter(p => p.includes(token)).length),
      deeper.some(p => /7\.5e1|9\.5e1/.test(p))] : deeper, [4, [1, 1, 1, 1], false])

  // D27 × P3（ADR-142）：requests、cost_ledger、budget_usd 写重复时读入只留最后一处 —— 不判的话按最后一处的计数、费用账或上限花钱。
  // 判据一侧：collect、render 在任务列表那一道只判 D19.k 以外那几处（outsideProgress），这三处照样各写成一条问题，被丢掉的前几处原文列得出来；
  // 夹具有效：同一份读入后的根预算、计数与费用账确实是最后一处的值。期望只来自 D27 × P3 裁决与夹具字面值
  const lastRead = P3.map(([, text]) => { const plain = JSON.parse(text); return [plain.budget_usd, plain.requests, plain.cost_ledger?.limit_micro_usd] })
  eq('费用字段写重复夹具有效：读入后根预算、请求计数与费用账上限都是最后一处的值（1 美元、0 次、1000000 微美元）',
    lastRead, P3.map(() => [1, 0, 1_000_000]))
  eq('费用字段写重复：requests、cost_ledger（整份或其中一项）、budget_usd 写重复时，只判进度键以外那几处的判据也各写成一条问题，按先后列出被丢掉的前几处原文',
    P3.flatMap(([name, text, at, tokens]) => {
      const got = scan(text)
      return 'outside' in got && got.outside.length === 1 && got.outside[0].includes(at) && inOrder(got.outside[0], tokens)
        ? [] : [`${name}: ${JSON.stringify(got)}`]
    }), [])
}

})
await group('d27-p3-entry', () => {
suite('D27', 'task.json 写重复的费用字段：collect 续跑与 enrich 改额在入口上以 2 拒绝')
{
  // 从 d19-resume 拆出（ADR-144）：这 10 次真入口启动只有 M-D27-h 用得到；留在 d19-resume 里，那一组的 39 条变异每条都要付一遍（需求测试选组不提前停）。
  // needs d19-resume：「费用字段写重复夹具有效」留在那一组，下面的以 2 退出要以它为前提，不然可能是最后一处本身不合规（ADR-144 复核发现 3）
  // 入口一侧：collect --resume --budget 2 与 enrich --budget 2 读到这几份任务，零改额（task.json 原字节）、零预留、零请求，以 2 退出。
  // 观测：fake-fetch 逐次记请求，预加载在 Budget.prototype.reserve 上记预留，armed 证明预加载真的装上了。
  // 阳性对照：同一份只留最后一处的任务、同一种接线，照常预留并请求（collect 去搜那个没完成的任务，enrich 去补那个创作者）
  const p3Root = mkdtempSync(join(tmpdir(), 'kol-d27-p3-'))
  try {
    const fakeFetch = pathToFileURL(join(process.cwd(), 'scripts', 'check', 'fake-fetch.ts')).href
    const budgetModule = pathToFileURL(join(process.cwd(), 'scripts', 'lib', 'budget.ts')).href
    const person = { platform: 'tiktok', handle: 'cost_person', nickname: 'cost_person', followers: 10000, post_count: 50, bio: null,
      bio_links: ['https://example.com'], verified: false, profile_url: '', source_keyword: 'local', source_dimension: 'category', recent_posts: [], fit: '✅' }
    let made = 0
    const runEntry = (entry: 'collect' | 'enrich', text: string) => {
      const cwd = join(p3Root, `run-${++made}`), taskDir = join(cwd, 'task'), file = join(taskDir, 'task.json')
      mkdirSync(join(cwd, 'memory'), { recursive: true }); mkdirSync(taskDir)
      writeFileSync(file, text)
      for (const name of ['creators.json', 'creators.raw.json']) writeFileSync(join(taskDir, name), JSON.stringify(entry === 'enrich' ? [person] : []))
      const ledger = join(cwd, 'attempts.tsv'), reserves = join(cwd, 'reserves.txt'), armed = join(cwd, 'armed.txt'), preload = join(cwd, 'observe-reserve.mjs')
      writeFileSync(reserves, '')
      writeFileSync(preload, [
        `import { appendFileSync } from 'node:fs';`,
        `import { Budget } from ${JSON.stringify(budgetModule)};`,
        `const original = Budget.prototype.reserve;`,
        `Budget.prototype.reserve = function(...args) { appendFileSync(${JSON.stringify(reserves)}, 'reserve\\n'); return Reflect.apply(original, this, args); };`,
        `appendFileSync(${JSON.stringify(armed)}, 'armed\\n');`,
      ].join('\n'))
      const argv = entry === 'collect' ? [join(process.cwd(), 'scripts', 'collect.ts'), '--resume', taskDir, '--budget', '2']
        : [join(process.cwd(), 'scripts', 'enrich.ts'), '--dir', taskDir, '--budget', '2']
      const kidEnv = { ...process.env, TIKHUB_API_KEY: 'fake-key-for-d27', FAKE_FETCH_LEDGER: ledger,
        FAKE_FETCH_NO_429: '1', NODE_COMPILE_CACHE: compileCacheDir(), NODE_OPTIONS: '' }
      kidEnv.NODE_OPTIONS = `--import ${JSON.stringify(fixtureLoader(argv[0], kidEnv, cwd))} --import ${JSON.stringify(fakeFetch)} --import ${JSON.stringify(pathToFileURL(preload).href)}`
      const [exe, args] = prebuiltCommand(argv, cwd, kidEnv)
      const r = spawnSync(exe, args, { cwd, encoding: 'utf8', env: kidEnv })
      const lines = (path: string) => existsSync(path) ? rf(path, 'utf8').split('\n').filter(Boolean).length : 0
      return { status: r.status, armed: lines(armed) > 0, kept: rf(file, 'utf8') === text, reserves: lines(reserves), attempts: lines(ledger),
        stderr: (r.stderr ?? '').split('\n').filter(Boolean).slice(-2).join(' | ') }
    }
    const entries = ['collect', 'enrich'] as const
    const controls = entries.map(entry => runEntry(entry, costText()))
    eq('费用字段写重复入口夹具有效：只留最后一处的同一份任务，collect --resume --budget 2 与 enrich --budget 2 照常预留并请求，观测确实装上了',
      controls.map(({ status, armed, reserves, attempts }) => [status, armed, reserves > 0, attempts > 0]), entries.map(() => [0, true, true, true]))
    const refused = entries.flatMap(entry => P3.map(([name, text]) => ({ at: `${entry}/${name}`, ...runEntry(entry, text) })))
    eq('费用字段写重复：collect --resume --budget 2 与 enrich --budget 2 见 requests、cost_ledger 或 budget_usd 写重复时以 2 退出，零改额（task.json 原字节）、零预留、零请求',
      refused.filter(({ status, armed, kept, reserves, attempts }) => !(status === 2 && armed && kept && reserves === 0 && attempts === 0)), [])
  } finally { rmSync(p3Root, { recursive: true, force: true }) }
  tension('D27', 'P3')
}

})
await group('p1-followers-sort', () => {
suite('P1', '排序：粉丝数「未查询」不被当成「已确认不够」')
{
  /**
   * 需求所有者 2026-09-19 裁决（ADR-92）：同层同分时，粉丝数分三档 ——
   * **已查到且不是 0 → 未查询 → 确实是 0**。未查询只压得过确认为 0 的人，
   * 压不过任何真查到了数的人。**只改先后，不改分也不改层。**
   */
  const FOLLOWERS: Record<string, number | undefined> = { big: 50_000, unknown: undefined, zero: 0 }
  const line = (...handles: string[]): Creator[] =>
    handles.map(h => mk('tiktok', h, { tier: 'B', score: 40, followers: FOLLOWERS[h] }))

  // 三档的先后。**正序逆序各排一次**：打平时排序稳定，比较器返回 0 就跟着输入
  // 顺序走 —— 只写一个方向，有一半的错写法照样绿，包括「这一条根本没生效」
  eq('三档先后：已查到的非 0 → 未查询 → 确实是 0',
     sortForOutput(line('big', 'unknown', 'zero')).map(c => c.handle), ['big', 'unknown', 'zero'])
  eq('把输入顺序整个颠倒，结论不变',
     sortForOutput(line('zero', 'unknown', 'big')).map(c => c.handle), ['big', 'unknown', 'zero'])

  // 两两各钉一次 —— 三个一起排时，只要有一档放对了，另一档错位也可能被挤回正确位置
  eq('未查询压得过确实是 0 的', sortForOutput(line('zero', 'unknown')).map(c => c.handle),
     ['unknown', 'zero'])
  eq('未查询压不过真查到了数的', sortForOutput(line('unknown', 'big')).map(c => c.handle),
     ['big', 'unknown'])
  eq('真查到了数的压得过确实是 0 的', sortForOutput(line('zero', 'big')).map(c => c.handle),
     ['big', 'zero'])

  // 这一条只在打平时说话，不许越过分数插队 —— 否则就等于偷偷给「未查询」加了分
  eq('分数仍然优先：分高的在前，哪怕他的粉丝数是已查到的 0',
     sortForOutput([
       mk('tiktok', 'low-unknown', { tier: 'B', score: 10, followers: undefined }),
       mk('tiktok', 'high-known', { tier: 'B', score: 40, followers: 0 }),
     ]).map(c => c.handle), ['high-known', 'low-unknown'])
  criterion('P1.h')
}

})
