await group('d20-content-version', () => {
suite('D20', '内容哈希版本按规范化 JSON 算出，复算只核对已有内容')
{
  // 依据 D20.f 与 ADR-136 2026-10-10 补记；期望值只来自下面的独立 oracle 与手推字符串，不借被测函数。
  const byCodePoint = (a: string, b: string): number => {
    const x = [...a], y = [...b]
    for (let i = 0; i < x.length && i < y.length; i++) {
      const d = (x[i].codePointAt(0) as number) - (y[i].codePointAt(0) as number)
      if (d !== 0) return d
    }
    return x.length - y.length
  }
  const oracleJson = (value: unknown, order: (a: string, b: string) => number = byCodePoint): string => {
    if (Array.isArray(value)) return `[${value.map(item => oracleJson(item, order)).join(',')}]`
    if (value !== null && typeof value === 'object') {
      const record = value as Record<string, unknown>
      return `{${Object.keys(record).sort(order)
        .map(key => `${JSON.stringify(key)}:${oracleJson(record[key], order)}`).join(',')}}`
    }
    return JSON.stringify(value)
  }
  const sha256Of = (text: string): string => 'sha256:' + createHash('sha256').update(text, 'utf8').digest('hex')
  const oracleHash = (value: unknown): string => sha256Of(oracleJson(value))
  const oracleVersion = (calibration: object): string =>
    oracleHash(Object.fromEntries(Object.entries(calibration).filter(([key]) => key !== 'version')))
  // 被测函数会抛时把抛出变成一个值，让断言红而不是让进程崩。
  const attempt = <T>(run: () => T): T | string => {
    try { return run() } catch (error) { return `threw: ${error instanceof Error ? error.message : String(error)}` }
  }
  const deepFreeze = <T>(value: T): T => {
    if (value !== null && typeof value === 'object') { for (const item of Object.values(value)) deepFreeze(item); Object.freeze(value) }
    return value
  }

  // 手推：键按码点 a < n < é < ～(U+FF5E) < 😀(U+1F600)，"10" 排在 "9" 前；-0 写成 0，1e21 写成 1e+21。
  const handVector = { '😀': [3, 'b', 1], '～': 'tilde', 'é': { z: true, '9': null, '10': false },
    a: 'ünï 中文 ～😀', n: [0.1, 1e21, -0, 1.5e-7, 100] }
  const HAND = '{"a":"ünï 中文 ～😀","n":[0.1,1e+21,0,1.5e-7,100],"é":{"10":false,"9":null,"z":true},"～":"tilde","😀":[3,"b",1]}'
  const pair = { '😀': 1, '～': 2 }
  const PAIR = '{"～":2,"😀":1}'
  const escapeVector = { s: 'line\n"q"\\\u0007', big: JSON.parse('1e999') as unknown }
  const ESCAPE = String.raw`{"big":null,"s":"line\n\"q\"\\\u0007"}`
  eq('内容哈希：独立 oracle 与手推的规范化字符串逐字相同',
    [oracleJson(handVector), oracleJson(pair), oracleJson(escapeVector)], [HAND, PAIR, ESCAPE])
  const utf16Pair = oracleJson(pair, (a, b) => a < b ? -1 : a > b ? 1 : 0)
  eq('内容哈希：码点序那一对键按 UTF-16 码元排会得到另一串和另一个哈希',
    [utf16Pair, sha256Of(utf16Pair) !== sha256Of(PAIR)], ['{"😀":1,"～":2}', true])

  eq('规范化 JSON：对象键按码点递归排序，数组保持原顺序，不含空白', attempt(() => canonicalJson(handVector)), HAND)
  eq('规范化 JSON：同层键 ～ 排在 😀 之前而不是按 UTF-16 码元排', attempt(() => canonicalJson(pair)), PAIR)
  eq('规范化 JSON：标量照 JSON.stringify 写，转义与溢出成无穷大的数字照它的结果', attempt(() => canonicalJson(escapeVector)), ESCAPE)
  // 手推：键 a 是 ab 的前缀，按码点短的在前；插入顺序故意把长的放前面，嵌套一层同样。
  const prefixVector = { ab: 1, a: 2, z: { yx: 1, y: 2 } }
  const PREFIX = '{"a":2,"ab":1,"z":{"y":2,"yx":1}}'
  eq('规范化 JSON：一个键是另一个键的前缀时短的排在前面，嵌套一层也一样',
    [attempt(() => canonicalJson(prefixVector)), oracleJson(prefixVector)], [PREFIX, PREFIX])
  eq('内容哈希：值是 sha256: 加规范化字符串按 UTF-8 编码后 SHA256 的小写十六进制',
    [handVector, pair, escapeVector].map(value => attempt(() => calibrationHash(value))),
    [sha256Of(HAND), sha256Of(PAIR), sha256Of(ESCAPE)])
  const nestedA = { outer: { b: [1, { y: 'deep', x: ['keep', 'order'] }], a: null }, top: '顶层' }
  const nestedB = { top: '顶层', outer: { a: null, b: [1, { x: ['keep', 'order'], y: 'deep' }] } }
  eq('内容哈希：嵌套对象换键的插入顺序不改变值，等于 oracle',
    [attempt(() => calibrationHash(nestedA)), attempt(() => calibrationHash(nestedB))], [oracleHash(nestedA), oracleHash(nestedA)])
  const listed = [1, 'a', { k: 1 }]
  const swapped = [{ k: 1 }, 'a', 1]
  eq('内容哈希：调换数组元素顺序改变值，各等于 oracle',
    [attempt(() => calibrationHash(listed)), attempt(() => calibrationHash(swapped)), oracleHash(listed) !== oracleHash(swapped)],
    [oracleHash(listed), oracleHash(swapped), true])
  eq('内容哈希：非 ASCII 字符串按 UTF-8 编码后算哈希',
    attempt(() => calibrationHash({ text: 'ünï 中文 ～😀' })), sha256Of('{"text":"ünï 中文 ～😀"}'))

  const hex = 'abcdef0123456789'.repeat(4)
  const accepted = ['sha256:' + hex, 'sha256:' + '0'.repeat(64), sha256Of(HAND)]
  eq('内容哈希版本格式：sha256: 加 64 位小写十六进制被认出',
    accepted.map(version => attempt(() => isContentVersion(version))), [true, true, true])
  const refused: { name: string; value: unknown }[] = [
    { name: 'uppercase hex', value: 'sha256:' + hex.toUpperCase() },
    { name: 'uppercase prefix', value: 'SHA256:' + hex },
    { name: '63 digits', value: 'sha256:' + hex.slice(1) },
    { name: '65 digits', value: 'sha256:' + hex + 'a' },
    { name: 'bare 64 hex', value: hex },
    { name: 'other algorithm', value: 'sha512:' + hex },
    { name: 'non-hex digits', value: 'sha256:' + 'g'.repeat(64) },
    { name: 'space after prefix', value: 'sha256: ' + hex.slice(1) },
    { name: 'leading space', value: ' sha256:' + hex },
    { name: 'trailing space', value: 'sha256:' + hex + ' ' },
    { name: 'trailing newline', value: 'sha256:' + hex + '\n' },
    { name: 'text on an earlier line', value: 'x\nsha256:' + hex },
    { name: 'brand label', value: 'brand-v1' },
    { name: 'empty', value: '' },
    { name: 'number', value: 256 },
    { name: 'null', value: null },
    { name: 'undefined', value: undefined },
    { name: 'array', value: ['sha256:' + hex] },
    { name: 'String object', value: new String('sha256:' + hex) },
  ]
  eq('内容哈希版本格式：大写、位数不符、缺前缀、前后空白与非字符串都不算',
    refused.filter(({ value }) => attempt(() => isContentVersion(value)) !== false).map(({ name }) => name), [])

  // D20.a 合规的校准，另带两个 D20.a 未列出的键（正是码点序那一对）；嵌套对象里也有一个叫 version 的键 ——
  // 「除 version 外的全部内容」只去掉顶层那一个，嵌套的照样进哈希。
  const calibration = {
    version: 'brand-v1',
    target_creator_types: ['home cooks', 'café owners'],
    tone_aesthetic: ['warm and practical'],
    natural_scenarios: ['preparing a weekday lunch', '周末野餐'],
    negative_signals: ['unexplained product claims'],
    sources: [
      { source: 'team brief, page 2', kind: 'brand_preference', detail: 'preferred voice' },
      { source: 'product page, checked 2026-09-30', kind: 'verified_product_fact', detail: 'page states the material' },
    ],
    '～': 'extra key outside D20.a',
    '😀': { note: 'extra nested key', '9': 1, '10': 2, version: 'inner' },
  }
  const base = oracleVersion(calibration)
  const versionOf = (value: object) => attempt(() => calibrationContentVersion(value))
  eq('校准内容版本：等于除 version 外全部内容（含 D20.a 未列出的键）的 oracle 哈希', versionOf(calibration), base)
  eq('校准内容版本：只改 version 不改变值',
    [versionOf({ ...calibration, version: 'brand-v2' }), versionOf({ ...calibration, version: base })], [base, base])
  const [first, second] = calibration.sources
  const without = (key: string) => Object.fromEntries(Object.entries(calibration).filter(([field]) => field !== key))
  const changes: { name: string; value: object }[] = [
    { name: 'target_creator_types appended', value: { ...calibration, target_creator_types: ['home cooks', 'café owners', 'students'] } },
    { name: 'target_creator_types swapped', value: { ...calibration, target_creator_types: ['café owners', 'home cooks'] } },
    { name: 'tone_aesthetic edited', value: { ...calibration, tone_aesthetic: ['warm and practical!'] } },
    { name: 'natural_scenarios swapped', value: { ...calibration, natural_scenarios: ['周末野餐', 'preparing a weekday lunch'] } },
    { name: 'negative_signals emptied', value: { ...calibration, negative_signals: [] } },
    { name: 'sources swapped', value: { ...calibration, sources: [second, first] } },
    { name: 'sources kind changed', value: { ...calibration, sources: [{ ...first, kind: 'verified_product_fact' }, second] } },
    { name: 'sources detail changed', value: { ...calibration, sources: [first, { ...second, detail: 'page states the size' }] } },
    { name: 'sources source changed', value: { ...calibration, sources: [{ ...first, source: 'team brief, page 3' }, second] } },
    { name: 'sources emptied', value: { ...calibration, sources: [] } },
    { name: 'extra key value changed', value: { ...calibration, '～': 'extra key changed' } },
    { name: 'extra nested value changed', value: { ...calibration, '😀': { ...calibration['😀'], '10': 3 } } },
    { name: 'nested version changed', value: { ...calibration, '😀': { ...calibration['😀'], version: 'inner-v2' } } },
    { name: 'nested version removed', value: { ...calibration, '😀': { note: 'extra nested key', '9': 1, '10': 2 } } },
    { name: 'extra key removed', value: without('😀') },
    { name: 'extra key added', value: { ...calibration, campaign: 'spring' } },
  ]
  eq('校准内容版本：改动或增删任一非 version 字段都换成该内容的 oracle 值',
    changes.filter(({ value }) => {
      const got = versionOf(value)
      return got !== oracleVersion(value) || got === base
    }).map(({ name }) => name), [])
  const frozenCalibration = deepFreeze(structuredClone(calibration))
  const frozenBefore = JSON.stringify(frozenCalibration)
  eq('校准内容版本：深冻结输入照算不抛，算后原值不变',
    [versionOf(frozenCalibration), JSON.stringify(frozenCalibration)], [base, frozenBefore])
  // 依据 D20.f「全部内容（含未列出的键）」：键下嵌多深都得算进哈希，规范化 JSON 对任何深度都有定义、不抛。
  // 期望串按构造写，不交给递归的 oracle；深对象也不交给 eq/ok 比较或打印（那本身会栈溢出）。
  // 每层两个成员、对象键按与码点序相反的顺序插入：只在浅层排序、只在浅层写分隔符、只对单成员链特判的写法在深处也露馅。
  const DEPTH = 100000
  let deepObject: unknown = 1, deepArray: unknown = 1
  for (let i = 0; i < DEPTH; i++) { deepObject = { b: 0, a: deepObject }; deepArray = [deepArray, 0] }
  const DEEP_OBJECT = '{"a":'.repeat(DEPTH) + '1' + ',"b":0}'.repeat(DEPTH), DEEP_ARRAY = '['.repeat(DEPTH) + '1' + ',0]'.repeat(DEPTH)
  // 几十万字符的长串只回报是否相等；不等时只给前 80 个字符（多半是 threw: …）。
  const sameLong = (got: unknown, want: string) => got === want || (typeof got === 'string' ? got.slice(0, 80) : typeof got)
  eq('规范化 JSON：十万层对象嵌套照常算出，不因深度抛错', sameLong(attempt(() => canonicalJson(deepObject)), DEEP_OBJECT), true)
  eq('规范化 JSON：十万层数组嵌套照常算出，不因深度抛错', sameLong(attempt(() => canonicalJson(deepArray)), DEEP_ARRAY), true)
  eq('内容哈希：十万层对象嵌套的值等于按构造写出的规范化串的 SHA256', attempt(() => calibrationHash(deepObject)), sha256Of(DEEP_OBJECT))
  // 合 D20.a 的校准另挂一个未列出的深键：oracle 只算浅的一层（深值先换成占位串），再把带引号的占位串换成构造串。
  const deepCalibration = { ...calibration, zz_extra: deepObject }
  const HOLE = 'zz-deep-placeholder'
  const shallow = oracleJson(Object.fromEntries(Object.entries({ ...calibration, zz_extra: HOLE }).filter(([key]) => key !== 'version')))
  const deepVersion = sha256Of(shallow.split(JSON.stringify(HOLE)).join(DEEP_OBJECT))
  const deepAccepted = attempt(() => brandCalibrationProblems({ brand_calibration: deepCalibration }))
  ok('深嵌套夹具有效：未列出的键挂十万层嵌套的校准通过已有的 D20.a 判定', Array.isArray(deepAccepted) && deepAccepted.length === 0)
  eq('校准内容版本：未列出的键挂十万层嵌套时照常算出，等于按构造推出的哈希', versionOf(deepCalibration), deepVersion)
  eq('版本复算：未列出的键挂十万层嵌套、版本与内容一致时返回空清单',
    attempt(() => calibrationVersionProblems({ product: 'deep-extra', brand_calibration: { ...deepCalibration, version: deepVersion } })), [])
  const deepStale = attempt(() => calibrationVersionProblems({ product: 'deep-extra', brand_calibration: { ...deepCalibration, version: 'sha256:' + '0'.repeat(64) } }))
  eq('版本复算：未列出的键挂十万层嵌套、版本不一致时恰好一条问题，指出 brand_calibration.version 并给出复算值',
    Array.isArray(deepStale) ? deepStale.map(problem => [typeof problem === 'string' && problem.includes('brand_calibration.version'),
      typeof problem === 'string' && problem.includes(deepVersion)]) : deepStale, [[true, true]])
  criterion('D20.f')

  // 回归（依据 D20.h 与 ADR-136 末尾那张既有缺陷的欠条）：三个入口把整份任务状态（含校准）交给评审准备，
  // 版本一致时须照常完成、不因校准嵌得深而抛错。复用上面的十万层夹具；结果与深对象都不交给 eq 比较或打印。
  const reviewDir = mkdtempSync(join(tmpdir(), 'kol-d20-deep-review-'))
  try {
    const deepState: Pick<TaskState, 'tasks'> & { brand_calibration: typeof deepCalibration } = {
      tasks: [{ keyword: 'lamp', dimension: 'category', platform: 'tiktok' }],
      brand_calibration: { ...deepCalibration, version: deepVersion },
    }
    const prepared = attempt(() => prepareTaskReviews(reviewDir, deepState, [], '2026-10-10T00:00:00Z', []))
    eq('评审准备：校准未列出的键挂十万层嵌套、版本一致时照常完成，不因深度抛错', typeof prepared === 'object' || String(prepared).slice(0, 80), true)
  } finally { rmSync(reviewDir, { recursive: true, force: true }) }

  // D20 × P1：复算只核对已有内容，不补字段、不改写版本；缺席或结构不合时不算哈希。
  const recheck = (state: object) => {
    const before = JSON.stringify(state)
    const got = attempt(() => calibrationVersionProblems(state))
    const frozen = deepFreeze(structuredClone(state))
    const frozenGot = attempt(() => calibrationVersionProblems(frozen))
    return { got, frozenGot, unchanged: JSON.stringify(state) === before && JSON.stringify(frozen) === before }
  }
  const consistent = { ...calibration, version: base }
  const edited = { ...consistent, tone_aesthetic: ['bold and loud'] }
  const recomputed = oracleVersion(edited)
  const absentState = { product: 'no-calibration', market: 'US' }
  const absent = recheck(absentState)
  eq('版本复算：brand_calibration 缺席时返回空清单，不给输入补出校准',
    [absent.got, absent.frozenGot, Object.hasOwn(absentState, 'brand_calibration'), absent.unchanged], [[], [], false, true])
  const structuralFixtures = [
    Object.fromEntries(Object.entries(edited).filter(([key]) => key !== 'negative_signals')),
    { ...edited, tone_aesthetic: [7] },
    { version: base },
  ]
  // 夹具自检（用已有的 D20.a 判定，不用被测的新函数）：下面「结构不合」的夹具确实被 D20.a 拒，
  // 「结构合规」的夹具确实不被拒 —— 否则空清单或那一条问题可能另有来由。
  const d20aRejects = (brand_calibration: unknown): boolean => {
    const got = attempt(() => brandCalibrationProblems({ brand_calibration }))
    return Array.isArray(got) && got.length > 0
  }
  const d20aAccepts = (brand_calibration: unknown): boolean => {
    const got = attempt(() => brandCalibrationProblems({ brand_calibration }))
    return Array.isArray(got) && got.length === 0
  }
  ok('版本复算夹具有效：三份结构不合的校准都被已有的 D20.a 判定拒绝', structuralFixtures.every(d20aRejects))
  ok('版本复算夹具有效：一致、改过内容与手写版本的校准都通过已有的 D20.a 判定',
    [consistent, edited, { ...edited, version: 'brand-v1' }, { ...edited, version: 'SHA256:' + base.slice(7) }].every(d20aAccepts))
  const structural = structuralFixtures.map(brand_calibration => recheck({ product: 'broken-calibration', brand_calibration }))
  eq('版本复算：结构不合 D20.a 时即使版本是哈希格式也不另算哈希',
    structural.map(({ got, frozenGot, unchanged }) => [got, frozenGot, unchanged]), [[[], [], true], [[], [], true], [[], [], true]])
  const handwritten = ['brand-v1', 'sha256:' + base.slice(7).toUpperCase(), 'SHA256:' + base.slice(7),
    'sha256:' + base.slice(8), 'sha256:' + base.slice(7) + '0']
    .map(version => recheck({ product: 'handwritten', brand_calibration: { ...edited, version } }))
  eq('版本复算：内容改了而版本不是内容哈希格式时不复算',
    handwritten.map(({ got, frozenGot, unchanged }) => [got, frozenGot, unchanged]),
    [[[], [], true], [[], [], true], [[], [], true], [[], [], true], [[], [], true]])
  const matched = recheck({ product: 'matched', brand_calibration: consistent })
  eq('版本复算：内容哈希版本与内容一致时返回空清单',
    [matched.got, matched.frozenGot, matched.unchanged], [[], [], true])
  const staleState = { product: 'stale', brand_calibration: edited }
  const stale = recheck(staleState)
  eq('版本复算：不一致时恰好一条问题，指出 brand_calibration.version 并给出按当前内容复算的值',
    Array.isArray(stale.got) ? stale.got.map(problem => [typeof problem === 'string' && problem.includes('brand_calibration.version'),
      typeof problem === 'string' && problem.includes(recomputed)]) : stale.got, [[true, true]])
  eq('版本复算：不一致时深冻结输入不抛，给出同样的问题',
    [Array.isArray(stale.frozenGot) && stale.frozenGot.length === 1, JSON.stringify(stale.frozenGot) === JSON.stringify(stale.got)], [true, true])
  eq('版本复算：不一致时不以复算值改写版本，输入原样',
    [Array.isArray(stale.got), stale.unchanged, staleState.brand_calibration.version], [true, true, base])
  tension('D20', 'P1')

  // `calibration version` 的判定（依据 D20.o、D20.p 与 D20 × P1 的命令一侧）：期望值只来自上面的 oracleVersion，不借被测函数。
  // 结果对象按键排好再比（键的先后不在要求之内）；抛出照原样成为 threw: … 的值。
  const sortedKeys = (got: unknown): unknown => typeof got === 'object' && got !== null
    ? Object.fromEntries(Object.entries(got).sort(([a], [b]) => byCodePoint(a, b))) : got
  const plan = (state: unknown): unknown => sortedKeys(attempt(() => planCalibrationVersion(state)))
  const listedOnly = Object.fromEntries(Object.entries(calibration).filter(([key]) => key !== '～' && key !== '😀'))
  // 下面两次传浅拷贝：被测函数若就地改写 version，后面复用的夹具不受牵连，红落在「不改写输入」那一条上。
  eq('校准版本命令：合 D20.a 的校准、version 是手写标签时要写入除顶层 version 外内容的内容哈希版本',
    plan({ product: 'listed-only', brand_calibration: { ...listedOnly } }), { action: 'write', version: oracleVersion(listedOnly) })
  eq('校准版本命令：D20.a 未列出的键与嵌套对象里叫 version 的键都算入要写入的值',
    plan({ product: 'extra-keys', brand_calibration: { ...calibration } }), { action: 'write', version: base })
  const staleVersions = ['brand-v2', 'sha256:' + base.slice(7).toUpperCase(), 'sha256:' + base.slice(8), 'sha256:' + '0'.repeat(64)]
  eq('校准版本命令：原 version 是手写标签、大写或位数不符的 sha256 串、与内容不一致的哈希时都换成按内容算出的值，不拒绝',
    staleVersions.map(version => plan({ product: 'stale-version', brand_calibration: { ...calibration, version } })),
    staleVersions.map(() => ({ action: 'write', version: base })))
  eq('校准版本命令：version 已等于按内容算出的值时判为不需要写入',
    plan({ product: 'current', brand_calibration: { ...calibration, version: base } }), { action: 'unchanged', version: base })

  // D20 × P1（命令一侧）：缺席不补出校准；不合 D20.a（含 null、version 缺席、空白或不是字符串）时只报结构问题、不另算哈希；
  // 哪种情况都不改写输入。输入里不放任何 sha256: 串，问题清单里出现它只能是算出来的。
  const judge = (state: object) => {
    const before = JSON.stringify(state)
    const got = plan(state), frozen = plan(deepFreeze(structuredClone(state)))
    return { got, frozenOk: typeof frozen === 'object' && JSON.stringify(frozen) === JSON.stringify(got), unchanged: JSON.stringify(state) === before }
  }
  const noCalibration = { product: 'no-calibration', market: 'US' }
  const absentPlan = judge(noCalibration)
  eq('校准版本命令：没有 brand_calibration 键时判为缺席，不给输入补出校准',
    [absentPlan.got, Object.hasOwn(noCalibration, 'brand_calibration')], [{ action: 'absent' }, false])
  const broken: unknown[] = [null, without('version'), { ...calibration, version: '   ' }, { ...calibration, version: 7 }, without('negative_signals'),
    { ...calibration, tone_aesthetic: [7] }, { ...calibration, natural_scenarios: [''] }, { ...calibration, sources: [{ ...first, kind: 'rumor' }, second] },
    { ...calibration, sources: [first, { ...second, detail: '' }] }, { ...calibration, sources: [{ ...first, source: '' }, second] }]
  ok('校准版本命令夹具有效：十份不合规的校准都被已有的 D20.a 判定拒绝', broken.every(d20aRejects))
  const brokenPlans = broken.map(brand_calibration => judge({ product: 'broken', brand_calibration }))
  const invalidShape = (got: unknown) => {
    const { action, problems } = (typeof got === 'object' && got !== null ? got : {}) as { action?: unknown; problems?: unknown }
    return Array.isArray(problems)
      ? [action, problems.length > 0, problems.every(problem => typeof problem === 'string' && !problem.includes('sha256:'))] : got
  }
  eq('校准版本命令：校准为 null、version 缺席、空白、不是字符串、缺 D20.a 必填字段、数组元素不是非空字符串或来源的性质、详情、出处不合规时判为不合规并列出问题，问题里没有哈希值',
    brokenPlans.map(({ got }) => invalidShape(got)), broken.map(() => ['invalid', true, true]))
  const purity = [absentPlan, ...brokenPlans, judge({ product: 'listed-only', brand_calibration: listedOnly })]
  eq('校准版本命令：缺席、不合规与要写入时都不改写输入，深冻结输入照判不抛且结果相同',
    purity.map(({ frozenOk, unchanged }) => [frozenOk, unchanged]), purity.map(() => [true, true]))

  // D20.o「写盘后」：写入的值写回再读仍自洽。写出时整数形的键会排到前面，规范化 JSON 对此不变。
  const roundText = `{"product":"round-trip","brand_calibration":${JSON.stringify(listedOnly).slice(0, -1)},"zz_extra":{"zz_big":1e400,"2024":"year"}}}`
  const roundCalibration = (JSON.parse(roundText) as { brand_calibration: object }).brand_calibration
  const roundVersion = oracleVersion(roundCalibration)
  ok('校准版本命令夹具有效：只含 D20.a 所列字段的校准与写回夹具里的校准都通过已有的 D20.a 判定',
    [listedOnly, roundCalibration].every(d20aAccepts))
  const rewritten = attempt(() => stringifyCostJson(readCostDocument(roundText)))
  ok('校准版本命令写回夹具有效：写出时整数形的键排到了原先在它前面的键之前',
    /"2024":\s*"year",\s*"zz_big":/.test(rewritten))
  const roundTrip = attempt(() => {
    const first = readCostDocument<{ brand_calibration: { version: unknown } }>(roundText)
    const planned = planCalibrationVersion(first)
    if (planned.action !== 'write') return [planned]
    first.brand_calibration.version = planned.version
    return [planned, planCalibrationVersion(readCostDocument(stringifyCostJson(first)))]
  })
  eq('校准版本命令：写入的值写回 task.json 再读入后，按内容判定仍等于该值、不需要再写',
    Array.isArray(roundTrip) ? roundTrip.map(sortedKeys) : roundTrip,
    [{ action: 'write', version: roundVersion }, { action: 'unchanged', version: roundVersion }])
  criterion('D20.o')
  criterion('D20.p')
  tension('D20', 'P1')

  // D19.n 的读写一侧（依据 D19.k、D19.n 原文与夹具字面值，没有读被测函数体；不认领 —— D19.n 由入口自检认领）：
  // 读入的 task.json 写重复了进度键、而要写盘时，抛出入口据以 2 退出的输入错误（函数签名处的约定），不写盘；
  // 问题点名重复的字段，并按文件先后写出每一处原文（前几处读入后不留痕迹，只有盘上原文里有）。不合 D20.a 时两类问题都在；
  // 缺席或 version 已一致时不写盘、照常返回。阳性对照是同一份文本只留最后一处：照常写入，盘上字节与修改时间确实变了。
  // 修改时间拨回过去：同字节重写也看得出
  const dupDir = mkdtempSync(join(tmpdir(), 'kol-d19n-'))
  try {
    const ledger = { schema: 1, currency: 'USD', unit: 'micro_usd', scope: 'task', limit_micro_usd: 1_000_000, next_attempt_id: 1, entries: [] }
    // [名, 写重复的进度原文, 只留最后一处的原文, 重复的字段, 按文件先后的每一处原文（对象不列）]
    const dupProgress: [string, string, string, string, string[]][] = [
      ['found-table', '"found":{"0":1e400,"0":3.000},"pages":{"0":1}', '"found":{"0":3.000},"pages":{"0":1}', 'found', ['1e400', '3.000']],
      ['pages-root', '"found":{"0":3},"pages":7.25e1,"pages":"zz-mid","pages":{"0":1}', '"found":{"0":3},"pages":{"0":1}', 'pages', ['7.25e1', 'zz-mid']],
    ]
    let made = 0
    const taskAt = (progress: string, brand?: object): string => {
      const dir = join(dupDir, `t${++made}`), file = join(dir, 'task.json')
      mkdirSync(dir)
      writeFileSync(file, `{"product":"d19n","market":"US","target_count":1,"budget_usd":1,"requests":0,"cost_ledger":${JSON.stringify(ledger)},`
        + `"tasks":[{"keyword":"lamp","dimension":"category","platform":"tiktok"}],"done":[0],"offsets":{"0":5},"answered":{"0":1},${progress},`
        + (brand === undefined ? '' : `"brand_calibration":${JSON.stringify(brand)},`)
        + `"created_at":"2026-01-01T00:00:00.000Z","updated_at":"2026-01-01T00:00:00.000Z"}\n`)
      utimesSync(file, new Date('2001-01-01'), new Date('2001-01-01'))
      return dir
    }
    const stampOf = (file: string) => { const s = statSync(file); return `${s.ino}:${s.mtimeMs}` }
    const runAt = (dir: string) => {
      const file = join(dir, 'task.json'), before = rf(file, 'utf8'), stamp = stampOf(file)
      let result: { status?: unknown; version?: unknown } | undefined, error: unknown
      try { result = runCalibrationVersion(dir) } catch (caught) { error = caught }
      const said = error instanceof Error ? error.message.split(dupDir).join('<D>') : ''
      return { result, error, said, kept: rf(file, 'utf8') === before && stampOf(file) === stamp }
    }
    const listedInOrder = (said: string, field: string, tokens: readonly string[]) => {
      let at = 0
      for (const token of tokens) { const i = said.indexOf(token, at); if (i < 0) return false; at = i + token.length }
      return said.includes(field)
    }
    const handVersion = { ...listedOnly, version: 'hand-v1' }, current = oracleVersion(listedOnly)
    const sameVersion = { ...listedOnly, version: current }
    const controls = dupProgress.map(([, , last]) => runAt(taskAt(last, handVersion)))
    const sameControls = dupProgress.map(([, , last]) => runAt(taskAt(last, sameVersion)))
    ok('校准版本命令重复进度键夹具有效：只留最后一处、version 是手写标签时照常写入，盘上字节与修改时间确实变了；version 已一致时判为不需要写入',
      controls.every(({ result, error, kept }) => error === undefined && result?.status === 'written' && !kept)
        && sameControls.every(({ result, error, kept }) => error === undefined && result?.status === 'unchanged' && kept))
    const writes = dupProgress.map(([, dup]) => runAt(taskAt(dup, handVersion)))
    eq('校准版本命令：进度键写了不止一次而要写盘时以输入问题拒绝（入口以 2 退出），不写盘，盘上原字节与修改时间不变',
      writes.map(({ error, kept }) => [error instanceof ReviewInputError, kept]), dupProgress.map(() => [true, true]))
    eq('校准版本命令：进度键写了不止一次而拒绝时，问题点名重复的字段并按文件先后写出每一处原文，不只最后一处',
      writes.map(({ said }, i) => listedInOrder(said, dupProgress[i][3], dupProgress[i][4])), dupProgress.map(() => true))
    const mixed = dupProgress.map(([, dup]) => runAt(taskAt(dup, { ...handVersion, tone_aesthetic: [7] })))
    eq('校准版本命令：进度键写了不止一次且 brand_calibration 不合 D20.a 时以输入问题拒绝、不写盘，两类问题都写出',
      mixed.map(({ error, said, kept }, i) => [error instanceof ReviewInputError, kept, said.includes('tone_aesthetic'),
        listedInOrder(said, dupProgress[i][3], dupProgress[i][4])]), dupProgress.map(() => [true, true, true, true]))
    const quiet = dupProgress.flatMap(([, dup]) => [runAt(taskAt(dup)), runAt(taskAt(dup, sameVersion))])
    eq('校准版本命令：brand_calibration 缺席或 version 已一致时进度键写了不止一次也不拒绝、不写盘，照常返回 absent 与 unchanged',
      quiet.map(({ result, error, kept }) => [error === undefined, result?.status, result?.status === 'unchanged' ? result?.version === current : true, kept]),
      dupProgress.flatMap(() => [[true, 'absent', true, true], [true, 'unchanged', true, true]]))
  } finally { rmSync(dupDir, { recursive: true, force: true }) }

  // D27.c 的读写一侧（依据 D27.a、D27.c 与 D27 × P1 原文、夹具字面值，没有读被测函数体；D27.c 不在这里认领 —— 由入口自检认领）：
  // task.json 任一层写重复了键（D19.k 那几处以外：根上的 tasks、任务对象里、进度值更深一层、requests、brand_calibration 里面）、
  // 而要写盘时，抛出入口据以 2 退出的输入错误，不写盘；问题写出键的位置并按文件先后写出每一处原文（前几处读入后不留痕迹，只有盘上原文里有）。
  // 不合 D20.a 时两类问题都在；缺席或 version 已一致时不写盘、照常返回，盘上的几处原样留着（D27 × P1）。
  // 阳性对照：同一份只留最后一处，照常写入，盘上字节与修改时间确实变了；修改时间拨回过去，同字节重写也看得出
  const d27Dir = mkdtempSync(join(tmpdir(), 'kol-d27c-'))
  try {
    const ledger = { schema: 1, currency: 'USD', unit: 'micro_usd', scope: 'task', limit_micro_usd: 1_000_000, next_attempt_id: 1, entries: [] }
    const PART = { tasks: '"tasks":[{"keyword":"lamp","dimension":"category","platform":"tiktok"}]', found: '"found":{"0":3}', requests: '"requests":0' }
    type Part = keyof typeof PART
    type Variant = { parts?: Partial<Record<Part, string>>; brandDup?: boolean }
    // [名, 写重复的那一份, 只留最后一处的那一份, 位置, 按文件先后被丢掉的前几处原文]
    const CASES: [string, Variant, Variant, string, string[]][] = [
      ['tasks-root', { parts: { tasks: `"tasks":"zq-first-list",${PART.tasks}` } }, {}, 'tasks', ['zq-first-list']],
      ['task-keyword', { parts: { tasks: '"tasks":[{"keyword":"zq\\u002dold","keyword":"lamp","dimension":"category","platform":"tiktok"}]' } }, {},
        'tasks[0]["keyword"]', ['zq\\u002dold']],
      ['found-deep', { parts: { found: '"found":{"0":{"zq":7.25e0,"zq":3}}' } }, { parts: { found: '"found":{"0":{"zq":3}}' } }, 'found["0"]["zq"]', ['7.25e0']],
      ['requests', { parts: { requests: '"requests":7.5e1,"requests":"zz-mid","requests":0' } }, {}, 'requests', ['7.5e1', 'zz-mid']],
      ['brand-inner', { brandDup: true }, {}, 'brand_calibration["natural_scenarios"]', ['zq-first-scene']],
    ]
    let made = 0
    const taskAt = ({ parts = {}, brandDup = false }: Variant, brand?: object): string => {
      const dir = join(d27Dir, `t${++made}`), file = join(dir, 'task.json')
      mkdirSync(dir)
      const brandText = brand === undefined ? undefined : brandDup
        ? JSON.stringify(brand).replace('"natural_scenarios":', '"natural_scenarios":"zq-first-scene","natural_scenarios":') : JSON.stringify(brand)
      writeFileSync(file, `{"product":"d27c","market":"US","target_count":1,"budget_usd":1,${parts.requests ?? PART.requests},"cost_ledger":${JSON.stringify(ledger)},`
        + `${parts.tasks ?? PART.tasks},"done":[0],"offsets":{"0":5},"answered":{"0":1},${parts.found ?? PART.found},"pages":{"0":1},`
        + (brandText === undefined ? '' : `"brand_calibration":${brandText},`)
        + `"created_at":"2026-01-01T00:00:00.000Z","updated_at":"2026-01-01T00:00:00.000Z"}\n`)
      utimesSync(file, new Date('2001-01-01'), new Date('2001-01-01'))
      return dir
    }
    const stampOf = (file: string) => { const s = statSync(file); return `${s.ino}:${s.mtimeMs}` }
    const runAt = (dir: string) => {
      const file = join(dir, 'task.json'), before = rf(file, 'utf8'), stamp = stampOf(file)
      let result: { status?: unknown; version?: unknown } | undefined, error: unknown
      try { result = runCalibrationVersion(dir) } catch (caught) { error = caught }
      const said = error instanceof Error ? error.message.split(d27Dir).join('<D>') : ''
      return { result, error, said, kept: rf(file, 'utf8') === before && stampOf(file) === stamp }
    }
    const listedInOrder = (said: string, at: string, tokens: readonly string[]) => {
      let i = 0
      for (const token of tokens) { const j = said.indexOf(token, i); if (j < 0) return false; i = j + token.length }
      return said.includes(at)
    }
    const handVersion = { ...listedOnly, version: 'hand-v1' }, current = oracleVersion(listedOnly)
    const sameVersion = { ...listedOnly, version: current }
    ok('校准版本命令写重复键夹具有效：brand_calibration 里确实有一处 natural_scenarios 可以写重复', JSON.stringify(handVersion).split('"natural_scenarios":').length === 2)
    const controls = CASES.map(([, , last]) => [runAt(taskAt(last, handVersion)), runAt(taskAt(last, sameVersion))])
    ok('校准版本命令写重复键夹具有效：只留最后一处、version 是手写标签时照常写入，盘上字节与修改时间确实变了；version 已一致时判为不需要写入',
      controls.every(([written, same]) => written.error === undefined && written.result?.status === 'written' && !written.kept
        && same.error === undefined && same.result?.status === 'unchanged' && same.kept))
    const writes = CASES.map(([, dup]) => runAt(taskAt(dup, handVersion)))
    eq('校准版本命令：task.json 任一层写重复了键而要写盘时以输入问题拒绝（入口以 2 退出），不写盘，盘上原字节与修改时间不变',
      writes.map(({ error, kept }) => [error instanceof ReviewInputError, kept]), CASES.map(() => [true, true]))
    eq('校准版本命令：任一层写重复了键而拒绝时，问题写出键的位置并按文件先后写出每一处被丢掉的原文，不只最后一处',
      writes.map(({ said }, i) => listedInOrder(said, CASES[i][3], CASES[i][4])), CASES.map(() => true))
    const mixedWrites = CASES.map(([, dup]) => runAt(taskAt(dup, { ...handVersion, tone_aesthetic: [7] })))
    eq('校准版本命令：任一层写重复了键且 brand_calibration 不合 D20.a 时以输入问题拒绝、不写盘，两类问题都写出',
      mixedWrites.map(({ error, said, kept }, i) => [error instanceof ReviewInputError, kept, said.includes('tone_aesthetic'),
        listedInOrder(said, CASES[i][3], CASES[i][4])]), CASES.map(() => [true, true, true, true]))
    // 缺席时没有 brand_calibration，里面那一处写重复也就无从谈起，那个用例只跑 version 已一致的一半
    const quiet = CASES.flatMap(([, dup]) => [...dup.brandDup ? [] : [runAt(taskAt(dup))], runAt(taskAt(dup, sameVersion))])
    eq('校准版本命令：brand_calibration 缺席或 version 已一致时任一层写重复了键也不拒绝、不写盘，照常返回 absent 与 unchanged，盘上几处原样留着',
      quiet.map(({ result, error, kept }) => [error === undefined, result?.status, result?.status === 'unchanged' ? result?.version === current : true, kept]),
      CASES.flatMap(([, dup]) => [...dup.brandDup ? [] : [[true, 'absent', true, true]], [true, 'unchanged', true, true]]))
    // 进度键与别处同时写重复（复核发现 3，写在接上实现之后）：D19.k 那几处照 D19.n 报、其余位置照 D27.c 报，两处都写出，同一处不报两遍
    const both = runAt(taskAt({ parts: { found: '"found":{"0":1e400,"0":3}', requests: '"requests":7.5e1,"requests":0' } }, handVersion))
    const times = (token: string) => both.said.split(token).length - 1
    eq('校准版本命令：进度键与别处同时写重复而要写盘时以输入问题拒绝、不写盘，两处都写出，每一处只写一遍',
      [both.error instanceof ReviewInputError, both.kept, times('1e400'), times('7.5e1')], [true, true, 1, 1])
  } finally { rmSync(d27Dir, { recursive: true, force: true }) }
  tension('D27', 'P1')
}
})

// D28 的夹具与入口接线（ADR-143），拆成下面几组共用（ADR-144）：模块级的只有只读的夹具与造入口的函数。
// 每组用 d28Run 各建各的根目录，run-N 在根下编号，组与组不共享目录
// D28（ADR-143）。测试先于实现、由另一个上下文写成：期望只来自 D28.a–d、D27.a 原文、D28 × P1 与 D28 × P3 的裁决和下面写进夹具的字面值；
// 没有读 collect.ts、probe.ts、cost-json.ts、duplicate-keys.ts 的函数体，也没有照着入口的输出抄。
// 每份夹具只有一处写重复，前几处是夹具里独有的写法（9.5e1、zq-old、7.25e0、zq-mid-two），最后一处就是基准那一份的值 ——
// 普通 JSON.parse 读出来与基准一模一样（第一条断言），前几处只在原文里找得到，stderr 里按先后找得到它们才是「每一处」。
// 观测与 D27 × P3 那一段同一种接法：fake-fetch 逐次记请求，预加载在 Budget.prototype.reserve 上记预留，armed 证明预加载装上了；
// 观测文件放在入口的工作目录之外，工作目录（配置文件、记忆、output/）整棵比。阳性对照是只留最后一处的同一份配置、同一种接线
const CFG = { market: '"market":"US"', budget: '"budget_usd":1', found: '"found":{"0":3}',
  tasks: '"tasks":[{"keyword":"local","dimension":"category","platform":"tiktok"}]' }
const cfg = (swap: Partial<Record<keyof typeof CFG, string>> = {}) =>
  `{"product":"d28dup",${swap.market ?? CFG.market},"target_count":1,${swap.budget ?? CFG.budget},${swap.tasks ?? CFG.tasks},${swap.found ?? CFG.found}}\n`
// at 是位置（照 D27.a：根上的键名往下接 [下标] 与 ["键"]），tokens 是按文件先后被丢掉的前几处原文（都不含位置本身，免得原文替位置作证），
// times 是出现次数，other 是同一份配置里另一类问题该写出的字段与原值
type Dup = { name: string; text: string; at: string; tokens: readonly string[]; times?: number; other?: readonly string[]; only?: 'collect' }
const DUPS: Dup[] = [
  // D28 × P3：根预算写重复，读入只留最后一处的 1 美元
  { name: 'budget_usd', text: cfg({ budget: '"budget_usd":9.5e1,"budget_usd":1' }), at: 'budget_usd', tokens: ['9.5e1'], times: 2 },
  // D28 × P1：任务里写了两次的 keyword，按最后一处新建的 task.json 里只会剩 local
  { name: 'keyword', text: cfg({ tasks: '"tasks":[{"keyword":"zq-old","dimension":"category","keyword":"local","platform":"tiktok"}]' }),
    at: 'tasks[0]["keyword"]', tokens: ['zq-old'], times: 2 },
  // D28.a：配置不续跑，根上的进度键与别的键一样报（D19.k 不适用）；写了三次，中间那一处的键名用转义写（按 JSON 解码后同名即算）
  { name: 'found', text: cfg({ found: '"found":7.25e0,"f\\u006fund":"zq-mid-two","found":{"0":3}' }), at: 'found', tokens: ['7.25e0', 'zq-mid-two'], times: 3 },
]
const d28Kit = (root: string) => {
  const fakeFetch = pathToFileURL(join(process.cwd(), 'scripts', 'check', 'fake-fetch.ts')).href
  const budgetModule = pathToFileURL(join(process.cwd(), 'scripts', 'lib', 'budget.ts')).href
  const tree = (dir: string) => JSON.stringify(readdirSync(dir, { recursive: true }).map(String).sort()
    .map(p => statSync(join(dir, p)).isDirectory() ? `${p}/` : `${p}:${rf(join(dir, p), 'base64')}`))
  const MODES = ['collect', 'collect --budget 2', 'probe'] as const
  type Mode = typeof MODES[number]
  let made = 0
  const runConfig = (mode: Mode, text: string, dup?: Dup) => {
    const run = join(root, `run-${++made}`), cwd = join(run, 'cwd'), obs = join(run, 'obs'), file = join(cwd, 'config.json')
    mkdirSync(join(cwd, 'memory'), { recursive: true }); mkdirSync(obs)
    writeFileSync(join(cwd, 'memory', 'creators.json'), JSON.stringify({ version: 1, updated_at: '2026-01-01T00:00:00.000Z', creators: {} }, null, 2) + '\n')
    writeFileSync(file, text)
    const before = tree(cwd)
    const ledger = join(obs, 'attempts.tsv'), reserves = join(obs, 'reserves.txt'), armed = join(obs, 'armed.txt'), preload = join(obs, 'observe-reserve.mjs')
    writeFileSync(reserves, '')
    writeFileSync(preload, [
      `import { appendFileSync } from 'node:fs';`,
      `import { Budget } from ${JSON.stringify(budgetModule)};`,
      `const original = Budget.prototype.reserve;`,
      `Budget.prototype.reserve = function(...args) { appendFileSync(${JSON.stringify(reserves)}, 'reserve\\n'); return Reflect.apply(original, this, args); };`,
      `appendFileSync(${JSON.stringify(armed)}, 'armed\\n');`,
    ].join('\n'))
    const argv = [join(process.cwd(), 'scripts', mode === 'probe' ? 'probe.ts' : 'collect.ts'), '--config', file,
      ...mode === 'collect --budget 2' ? ['--budget', '2'] : []]
    const kidEnv = { ...process.env, TIKHUB_API_KEY: 'fake-key-for-d28', FAKE_FETCH_LEDGER: ledger,
      FAKE_FETCH_NO_429: '1', NODE_COMPILE_CACHE: compileCacheDir(), NODE_OPTIONS: '' }
    kidEnv.NODE_OPTIONS = `--import ${JSON.stringify(fixtureLoader(argv[0], kidEnv, cwd))} --import ${JSON.stringify(fakeFetch)} --import ${JSON.stringify(pathToFileURL(preload).href)}`
    const [exe, args] = prebuiltCommand(argv, cwd, kidEnv)
    const r = spawnSync(exe, args, { cwd, encoding: 'utf8', env: kidEnv })
    const lines = (path: string) => existsSync(path) ? rf(path, 'utf8').split('\n').filter(Boolean).length : 0
    // 路径先移走：它不能替问题提供位置、原文或次数
    const stderr = r.stderr ?? '', message = stderr.replaceAll(file, '[配置]').replaceAll(root, '[目录]')
    return { ...dup, mode, status: r.status, armed: lines(armed) > 0, reserves: lines(reserves), attempts: lines(ledger), kept: rf(file, 'utf8') === text,
      same: tree(cwd) === before, made: existsSync(join(cwd, 'output')), stdout: r.stdout ?? '', pathSaid: stderr.includes(file), message, tail: message.split('\n').filter(Boolean).slice(-3).join(' | ') }
  }
  type Got = ReturnType<typeof runConfig>
  const brief = (g: Got) => `${g.mode}/${g.name ?? '-'}: exit=${g.status} armed=${g.armed} reserves=${g.reserves} attempts=${g.attempts}`
    + ` 配置原字节=${g.kept} 目录原样=${g.same} stdout=${g.stdout.length}字 stderr=${g.tail}`
  const inOrder = (text: string, tokens: readonly string[]) => {
    let at = 0
    for (const token of tokens) { const i = text.indexOf(token, at); if (i < 0) return false; at = i + token.length }
    return true
  }
  // 拒绝：退出 2，预留与请求都是零（观测装上了），配置文件原字节，工作目录整棵不变 —— 没有任务目录、没有写记忆
  const held = (g: Got) => g.status === 2 && g.armed && g.reserves === 0 && g.attempts === 0 && g.kept && g.same
  // 列出：配置文件路径、位置、按先后每一处被丢掉的原文；出现次数在写着第一处原文的那一行里（写了两次的 2，三次的 3）
  const listed = (g: Got) => g.status === 2 && g.pathSaid && g.message.includes(g.at!) && inOrder(g.message, g.tokens!)
    && (g.times === undefined || (g.times === 2 ? /[2两二]/ : /[3三]/).test(g.message.split('\n').find(line => line.includes(g.tokens![0])) ?? ''))
  // F3.c：内部异常的类名（以 Error 结尾的标识符）与栈帧（行首空白加 at ）都不出现
  const leaks = (g: Got) => /\b[A-Za-z]*Error\b/.test(g.message) || /^\s+at\s/m.test(g.message)
  return { MODES, runConfig, brief, inOrder, held, listed, leaks }
}
type D28Got = ReturnType<ReturnType<typeof d28Kit>['runConfig']>
const d28Run = (run: (kit: ReturnType<typeof d28Kit>) => void) => {
  const root = mkdtempSync(join(tmpdir(), 'kol-d28-'))
  try { run(d28Kit(root)) } finally { rmSync(root, { recursive: true, force: true }) }
}
// 各组跑完时记下自己；旧组名 d28-config-duplicates 只在六组都在时认领 D28.a–d
const d28Done = new Set<string>()

await group('d28-control', () => {
suite('D28', '配置写重复的键：夹具有效与入口阳性对照')
{
d28Run(({ MODES, runConfig, brief, inOrder, held, listed, leaks }) => {
  eq('配置写重复的键夹具有效：每一份经普通 JSON.parse 读成与只留最后一处的那一份相同，前几处读入后不留痕迹',
    DUPS.filter(({ text }) => !isDeepStrictEqual(JSON.parse(text), JSON.parse(cfg()))).map(({ name }) => name), [])
  const controls = MODES.map(mode => runConfig(mode, cfg()))
  eq('配置写重复的键入口夹具有效：只留最后一处的同一份配置，collect --config、collect --config --budget 2 与 probe 照常以 0 结束、预留并请求，观测确实装上了；collect 建了任务目录、probe 往 stdout 写了结果',
    controls.map(g => [g.status, g.armed, g.reserves > 0, g.attempts > 0, g.mode === 'probe' ? g.stdout.trim() !== '' : g.made]),
    MODES.map(() => [0, true, true, true, true]))
  if (controls.some(g => g.status !== 0 || g.reserves === 0 || g.attempts === 0)) console.log(`     ${controls.map(brief).join('\n     ')}`)
  d28Done.add('d28-control')
})
}
})
await group('d28-collect', () => {
suite('D28', 'collect --config 见配置写重复的键以 2 拒绝并按先后列出每一处')
{
d28Run(({ MODES, runConfig, brief, inOrder, held, listed, leaks }) => {
  const collects = MODES.filter(mode => mode !== 'probe').flatMap(mode => DUPS.map(dup => runConfig(mode, dup.text, dup)))
  eq('collect --config（含 --budget 2）见配置任一层写重复的键（根上的 budget_usd、任务里的 keyword、根上的进度键 found）以 2 退出：零预留、零请求，不建任务目录、不写任何文件与记忆，配置文件原字节',
    collects.filter(g => !held(g)).map(brief), [])
  eq('collect --config 拒绝时 stderr 写出配置文件路径、键的位置与出现次数，并按文件先后写出每一处被丢掉的原文',
    collects.filter(g => !listed(g)).map(brief), [])
  d28Done.add('d28-collect')
})
}
})
await group('d28-probe', () => {
suite('D28', 'probe 见配置写重复的键以 2 拒绝并按先后列出每一处')
{
d28Run(({ MODES, runConfig, brief, inOrder, held, listed, leaks }) => {
  const probes = DUPS.map(dup => runConfig('probe', dup.text, dup))
  eq('probe 见配置任一层写重复的键以 2 退出：零预留、零请求，stdout 为空，工作目录与配置文件原字节',
    probes.filter(g => !(held(g) && g.stdout === '')).map(brief), [])
  eq('probe 拒绝时 stderr 写出配置文件路径、键的位置、出现次数与按文件先后每一处被丢掉的原文，不带内部异常的类名与调用堆栈',
    probes.filter(g => !listed(g) || leaks(g)).map(brief), [])
  d28Done.add('d28-probe')
})
}
})
await group('d28-mixed', () => {
suite('D28', '配置写重复的键与任务列表、市场、路线或品牌问题一起报')
{
d28Run(({ MODES, runConfig, brief, inOrder, held, listed, leaks }) => {
  // D28.b、D28.c「一起」：同一份配置里另有任务列表（D16）、市场（D17）、路线（D15）或品牌（D20，只有 collect 判）的问题。退出 2 本来就由那一类问题满足，要的是两类在同一次拒绝里都写出，
  // 不让用户先照最后一处改完任务、再撞上写重复。任务问题按 D16.d 认字段名与 JSON 原值，市场问题按 D17.d 认字段与原值
  const MIXED: Dup[] = [
    { name: 'with-task-list', at: 'tasks[0]["keyword"]', tokens: ['zq-old'], other: ['dimension', '"zq-bad-dim"'],
      text: cfg({ tasks: '"tasks":[{"keyword":"zq-old","dimension":"category","keyword":"local","platform":"tiktok"},{"keyword":"local","dimension":"zq-bad-dim","platform":"tiktok"}]' }) },
    { name: 'with-market', at: 'found', tokens: ['7.25e0'], other: ['market', 'zq-bad-market'],
      text: cfg({ market: '"market":["zq-bad-market"]', found: '"found":7.25e0,"found":{"0":3}' }) },
    // 复核之后由写实现的上下文补（ADR-143 第五节）：路线问题（D15.j，第几个任务、哪一条）与品牌问题（D20.e，只有 collect 判）
    { name: 'with-route', at: 'budget_usd', tokens: ['9.5e1'], other: ['ig_route', 'zq-bad-route'],
      text: cfg({ budget: '"budget_usd":9.5e1,"budget_usd":1',
        tasks: '"tasks":[{"keyword":"local","dimension":"category","platform":"tiktok"},{"keyword":"local-two","dimension":"scene","platform":"instagram","ig_route":"zq-bad-route"}]' }) },
    { name: 'with-brand', at: 'found', tokens: ['7.25e0'], other: ['brand_calibration'], only: 'collect',
      text: cfg({ found: '"found":7.25e0,"found":{"0":3},"brand_calibration":"zq-bad-brand"' }) },
  ]
  const mixed = (['collect', 'probe'] as const).flatMap(mode => MIXED.filter(dup => !dup.only || dup.only === mode).map(dup => runConfig(mode, dup.text, dup)))
  eq('写重复的键与同一份配置里的任务列表、市场、路线或品牌问题一起：collect --config 与 probe 以 2 退出、零预留零请求、目录与配置原样，stderr 写出写重复的那一处与被丢掉的原文',
    mixed.filter(g => !(held(g) && listed(g))).map(brief), [])
  eq('写重复的键与同一份配置里的任务列表、市场、路线或品牌问题一起：那一类问题不被写重复遮住，stderr 照写出字段与原值',
    mixed.filter(g => !(g.status === 2 && g.other!.every(s => g.message.includes(s)))).map(brief), [])
  d28Done.add('d28-mixed')
})
}
})
await group('d28-defaults', () => {
suite('D28', '配置写重复的键被拒时不先套缺省')
{
d28Run(({ MODES, runConfig, brief, inOrder, held, listed, leaks }) => {
  // 复核之后由写实现的上下文补（ADR-143 第五节）：D17.l 只在相关配置问题都消除后才套缺省 —— 写重复的键被拒时，
  // 配置里没写的 market 与 budget_usd 不该先被说成采用了默认。对照是只留最后一处的同一份，要照常以 0 结束并说明默认，证明认得出那句话。
  // 它不核预留与请求，held() 的零预留零请求以 d28-control 的入口对照为前提，所以 needs 它（ADR-144 复核发现 1）
  const bareText = (found: string) => `{"product":"d28dup","target_count":1,${CFG.tasks},${found}}\n`
  const BARE: Dup = { name: 'no-defaults', at: 'found', tokens: ['7.25e0'], text: bareText('"found":7.25e0,"found":{"0":3}') }
  const bare = (['collect', 'probe'] as const).flatMap(mode => [runConfig(mode, bareText(CFG.found)), runConfig(mode, BARE.text, BARE)])
  const defaulted = (g: D28Got) => /默认|缺省|default/i.test(g.message)
  eq('写重复的键被拒时不先套缺省：配置里没写 market 与 budget_usd，collect --config 与 probe 以 2 退出、零预留零请求，stderr 写出写重复的那一处，不说采用了默认市场或默认预算（只留最后一处的同一份照常以 0 结束并说明默认）',
    bare.filter(g => g.name === undefined ? !(g.status === 0 && defaulted(g)) : !(held(g) && listed(g)) || defaulted(g)).map(brief), [])
  d28Done.add('d28-defaults')
})
}
})
await group('d28-no-overreject', () => {
suite('D28', '配置写重复的键不多拒')
{
d28Run(({ MODES, runConfig, brief, inOrder, held, listed, leaks }) => {
  // D28.d 不多拒：不同对象里的同名键（每个任务各有 keyword，值各不相同）与数组里相同的元素（后两个任务一模一样）都不算写重复
  const SAME = cfg({ tasks: '"tasks":[{"keyword":"local","dimension":"category","platform":"tiktok"},'
    + '{"keyword":"local-two","dimension":"scene","platform":"tiktok"},{"keyword":"local-two","dimension":"scene","platform":"tiktok"}]' })
  const normal = (['collect', 'probe'] as const).map(mode => runConfig(mode, SAME))
  eq('写重复的键不多拒：各个任务各有 keyword 与任务数组里一模一样的两项不算写重复，collect --config 与 probe 照常以 0 结束、预留并请求',
    normal.map(g => [g.status, g.armed, g.reserves > 0, g.attempts > 0]), normal.map(() => [0, true, true, true]))
  d28Done.add('d28-no-overreject')
})
}
})
await group('d28-config-duplicates', () => {
suite('D28', 'collect --config 与 probe 读的配置写重复的键：在建目录、开账、预留与请求之前以 2 拒绝，按先后列出每一处')
{
  // 旧组名保留为完整入口（ADR-144，照 ADR-131）：needs 拉齐上面六组，六组都跑完才认领。
  // 下面这条只为满足「每组至少执行一条断言」：哪一组没跑完，group() 先就抛了，它红不了
  const parts = ['d28-control', 'd28-collect', 'd28-probe', 'd28-mixed', 'd28-defaults', 'd28-no-overreject']
  eq('配置写重复的键：拆开的六组都跑完', parts.filter(id => !d28Done.has(id)), [])
  criterion('D28.a', 'D28.b', 'D28.c')
  tension('D28', 'P1')
  tension('D28', 'P3')
  criterion('D28.d')
}
})


